-- Durable user-authored routines over the attributed reference library.
-- These records remain explicitly unreviewed references and do not enter the
-- clinical catalog, screening, or automatic progression systems.

CREATE TABLE public.training_reference_library_records (
  reference_id text PRIMARY KEY CHECK (reference_id ~ '^wger:[0-9a-f-]{36}$'),
  snapshot_id text NOT NULL CHECK (snapshot_id IN (
    'wger-english-2026-09-08','wger-1652-media-pilot-2026-09-08'
  )),
  source_record_id bigint NOT NULL CHECK (source_record_id > 0),
  source_record_updated_at timestamptz NOT NULL,
  record_sha256 text NOT NULL CHECK (record_sha256 ~ '^[a-f0-9]{64}$'),
  display_json jsonb NOT NULL,
  UNIQUE (snapshot_id, source_record_id),
  CHECK ((private.jsonb_has_exact_keys(display_json, ARRAY[
    'name','instructions','equipment','media','source'
  ])) IS TRUE)
);

INSERT INTO public.training_reference_library_records(
  reference_id,snapshot_id,source_record_id,source_record_updated_at,record_sha256,display_json
) VALUES
  ('wger:d561c00c-436d-47d9-b647-222e7b637abd','wger-english-2026-09-08',1966,'2026-06-19T18:48:20.207400+02:00','9d38470906eb5575f70af283b5928545677888b1b459952ab6b406420f826e8a','{"name":"1/2 Kneeling Thoracic Rotation","instructions":"Begin in a half kneeling position with the leg away from the wall stabilized against the wall with a ball. With both hands directly in front of you, rotate one arm open attempting to reach the wall behind you. Exhale as you rotate, inhale as you return to neutral and repeat.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1966/","author":"amwang4","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:a8a4ea81-9531-48e1-b6dc-f7621c7b9283','wger-english-2026-09-08',1470,'2026-07-23T12:36:32.061160+02:00','d93c23fc39a6fa22ab22e1a5d39ffc8cd3411f0948791f047b523f1e23706b76','{"name":"1-Arm Half-Kneeling Lat Pulldown","instructions":"Attach a D-Handle to a high pully. And use your lat muscles to pull the weight single handedly.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1470/","author":"Expenses7000","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:c463f618-2777-4836-9c57-92a46d87cf1b','wger-english-2026-09-08',1948,'2026-06-19T18:56:12.035751+02:00','2a5402a23b3574b96d20f25c88398d2e5ad39bbf6c070f0bff1d7d068b506c43','{"name":"1 Leg Box Squat","instructions":"This exercise requires a sturdy box or a chair. Simple stand ~6 inches in front of it and balance yourself on one leg. From here, begin squatting down in a smooth controlled motion while keeping your other leg straight out in front of you for balance. Slowly sit down on the box, pause for a 1 count and push back up with the working leg, while never letting your other leg touch the ground.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1948/","author":"jesusd","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:7c2a70bc-ed97-440c-afd6-ed27daf63f25','wger-english-2026-09-08',1115,'2026-06-19T18:49:54.643526+02:00','926fccbd1a005406e4072e4ffe6b82634f4d69225730b8c92de26250f12182c7','{"name":"3D lunge warmup","instructions":"As a warmup, use light dumbbells, one in each hand. Lunge in alternating directions, forward, sideways, backwards and 45 degree angles.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1115/","author":"philip","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:203a6fee-7436-4313-858f-c1e364136793','wger-english-2026-09-08',1573,'2026-06-19T18:54:16.316438+02:00','12e549835340e3c827995cb515e0e6286006129c0db54023b7edeb2004cdbfb8','{"name":"Ab wheel","instructions":"Starting Position : Kneel on the floor with the ab wheel in front of you. Grip the Wheel : Hold the handles firmly. Roll Out : Slowly roll the wheel forward, extending your body while keeping your core tight. Return : Pull the wheel back towards your knees, maintaining tension in your core.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1573/","author":"lhegedus","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:2ac901e6-f0c2-416f-998f-e01e00fe0aa1','wger-english-2026-09-08',1933,'2026-06-19T18:56:43.175832+02:00','596dbc9fef058e8638939d28f8fdbd786d519bbed5523e0436f685d5374adfff','{"name":"Abdominal Crunch","instructions":"The Abdominal Crunch is a classic core isolation exercise performed on the floor or a mat. Unlike a full sit-up, it involves a smaller range of motion where you only lift your shoulders and upper back off the ground, keeping your lower back pressed firmly against the floor.","equipment":["Gym mat"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1933/","author":"amaesc","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:793b0e5f-8dea-48a6-84c8-9123b59c2721','wger-english-2026-09-08',1828,'2026-06-19T18:55:40.679499+02:00','6df4e02f25ddb43ece0dcd251c29abe6b871f1fabfe0a7925a8119288c62ccc7','{"name":"Abdominal Draw-In","instructions":"Lie on your back with knees bent. Gently pull your belly button toward your spine without moving your hips or holding your breath.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1828/","author":"beagle","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:d015a276-02ad-4c28-9d36-aedfbb431f53','wger-english-2026-09-08',1096,'2026-06-19T18:49:45.885236+02:00','c62d6a12f8eedbce89696eb470bf513b61584644501bb606a222fb7f985747e6','{"name":"Abduction while standing","instructions":"Training a stable stance, predominantly on one leg, is crucial for both sides. On the one hand, it prevents discomfort and, on the other, it establishes a stable foundation. The practitioner assumes the usual standing position and, with a stable upper body, attempts to repeatedly lift the unloaded leg, bend it at the hip and knee, and then lower it again. The movement is also repeated on the other side. The exercise trains the stability of the hip-surrounding muscles.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1096/","author":"tregga","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:d02f6fe0-8ae3-4251-8f94-a63e38249a55','wger-english-2026-09-08',2491,'2026-08-05T11:16:08.381934+02:00','e376657dfd946948c2c485de251a4ec48123fcf0b781b10b6c0646ae8d9244f2','{"name":"Abductors","instructions":"Based on Abductors Sel. by Technogym. Position yourself on the machine and open your legs as much as possible. Return slowly to the original position.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2491/","author":"lbroggi","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:1c60ade0-1e8c-475b-b2d3-bfdf313987f4','wger-english-2026-09-08',2493,'2026-08-05T16:19:50.580436+02:00','383d33d904c6a926a1c5f67806e35707f5c1a188f7c6150e41e787c6ef5f1408','{"name":"Adductor Side Plank","instructions":"Set up next to a bench in a 90° angle on your side. One leg goes up on the bench with the side of your calf touching it. The other leg goes below the bench. Forearm closer to the ground is at a 90° angle, hand pointing front. Now push off the floor with the forearm closer to the ground, upper side of your body should be completely straight, level with the bench (it''s a side plank after all). Hold that position.","equipment":["Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2493/","author":"hurr99","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:701d9cee-0797-4177-8556-252de669b56c','wger-english-2026-09-08',2492,'2026-08-05T11:18:54.536138+02:00','7d4eac6da51bba65b2b153da7d5535c72299482f573adffd2cc0e83ccb11eff5','{"name":"Adductors","instructions":"Based on Adductor Sel. by Technogym. Sit on the machine and set the rest position to a comfortable opening angle. Close your legs. Gently return to the rest position.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2492/","author":"lbroggi","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:5831bcbb-28a7-4bd5-930d-a740acccf747','wger-english-2026-09-08',1102,'2026-04-15T22:23:52.633301+02:00','1b1e73906b8a83b8c73a2e7b8ac4718a09cd75f18552f9e6f9ff5ae1a1be896b','{"name":"Alternate back lunges","instructions":"The posterior muscles of the buttocks, hamstrings, soleus and gastrocnemius are trained more","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1102/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:94238bef-15ee-42b6-8035-79854b3c6e65','wger-english-2026-09-08',1192,'2026-06-19T19:55:15.953897+02:00','075a8bbd0c327d7d9732a95c464399d6d36d1b842dba3f4ab0e6a4660cd91b6c','{"name":"Alternating Biceps Curls With Dumbbell","instructions":"Hold two dumbbells, the arms are streched, the hands are on your side, the palms face inwards. Bend one arm at a time and bring the weight with a fast movement up. At the same time, rotate your arms by 90 degrees at the very beginning of the movement. At the highest point, rotate a little the weights further outwards. Without a pause, bring the arm back down, slowly, and do the same with the other arm. Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1192/","author":"Franpol","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:eb9476ac-2c00-4f49-a40f-f81682161a75','wger-english-2026-09-08',1567,'2026-06-19T18:47:09.433435+02:00','a4a7a46bc863c34e1e18cc9180b5a53088fe2d4fe692c6c2f5706b856db56836','{"name":"Alternating dumbbell hammer curl","instructions":"Stand with your knees slightly bent and your back straight. Hold a dumbbell in each hand, using a neutral grip at your sides.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1567/","author":"Mariano_O","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:45251627-5f89-4858-bf0c-8884a21cbb1f','wger-english-2026-09-08',1486,'2026-07-23T12:36:34.551384+02:00','faf8eafbd4060f294b3a832433ba108795f7b73fb2ba1aa1dfdef5c5cd50b70c','{"name":"Alternating High Cable Row","instructions":"Start by putting the attachment in a high position on the cable station and step back about 1m from the attachment. Grab the cable pulley handle in your left hand at about head height with your elbow slightly bent. Step back with your left foot. Pull your elbow joint in toward the torso twisting slightly and perform a single-arm row. Engage the lats as you twist. Return to the starting position with cable pulley and left foot and grab the cable pulley handle in the right hand. Repeat this motion on the opposite side with your right foot stepped back.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1486/","author":"Moffi","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:81015468-545f-4170-9b46-701afe77848e','wger-english-2026-09-08',1501,'2026-06-19T18:53:25.940329+02:00','b95329f76d282f6007b13e9a69286a756842f9fe611b144470d263fd10c05eb4','{"name":"Alternative DB Gorilla rows","instructions":"Slightly bent down and knees to mimic a gorilla position and pull/row up the DBs to the chest. DB stay straight (thumbs pointing up)","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1501/","author":"JohnPreston","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:fa5252d3-973c-4b35-9324-a02460545283','wger-english-2026-09-08',1804,'2026-06-19T18:55:27.154808+02:00','a7c849a01d2d0b114689313857b984c5652864031880e39437f639265e6817a2','{"name":"ankle dorsiflexion rocks","instructions":"Move your knee forward, keeping your heel on the ground. Hold the position for a couple of seconds and return to the starting position.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1804/","author":"Davidgj32","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:7dd7a735-c1fe-4ca0-a6e8-e825d897b065','wger-english-2026-09-08',1141,'2026-06-19T18:50:07.133732+02:00','44ab179fe6c98eff476d6a61bb34e4f579e73ca11a8263e58ba656930d6ab350','{"name":"Arabesque","instructions":"Take all your weight onto one leg and you''re going to maintain that position, keeping your hips and pelvis level the whole time. With your back in a neutral position you want to tilt yourself forward kicking your leg back up and then slowly with your glutes bring yourself back up to neutral.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1141/","author":"cleen","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:56808c52-050e-4c24-9f27-2657f0462499','wger-english-2026-09-08',1545,'2026-08-26T19:46:49.499648+02:00','8529a2c5798c4cfc6e71c99e5639886067c8ab7cb694a42b9a07cf634bb37729','{"name":"Archer Pull Up","instructions":"An archer pull-up is an advanced bodyweight exercise that strengthens your back and biceps, serving as a progression towards a one-arm pull-up. It gets its name from the \"bow-drawing\" position your body takes at the top.Here''s how to do it: Grip: Grasp a pull-up bar with a wider-than-shoulder-width overhand grip. Starting Position: Hang with arms fully extended, engaging your core and keeping your shoulder blades pulled down. The Pull: Pull your body up towards one hand, similar to a regular pull-up. At the same time, extend the other arm out to the side, keeping it as straight as possible. Your chin should come towards the hand that is pulling. Hold & Lower: Briefly hold the top position where one arm is bent and pulling, and the other is extended. Slowly lower yourself back to the starting position with control. Alternate: Repeat the movement, pulling up towards the opposite hand.The key to this exercise is to keep the assisting arm as straight as possible to maximise the load on the working arm. This makes it a challenging but effective exercise for unilateral pulling strength.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1545/","author":"Antsy6277","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b48cd640-dd9f-4557-a4db-8cd33d5655a6','wger-english-2026-09-08',1590,'2026-06-19T18:54:28.350872+02:00','937da041ac1bdbf717a6e799c6ba12b3e869b33cf626d05454752863434bda01','{"name":"Arm and neck stretch","instructions":"Relieves tension in the upper body, especially useful for people with office jobs or prolonged postures.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1590/","author":"MrAlfaRobot","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:e62d52fa-32f9-4747-9005-f88f05dc8334','wger-english-2026-09-08',1606,'2026-06-19T18:54:40.670392+02:00','c5c2bb9d99fa0e74db0016a65316f2bfff933058fd636dbabb46227cfae694a6','{"name":"Arm Raises (T/Y/I)","instructions":"Stand upright with feet hip-width apart, core engaged, and arms relaxed at your sides. From this position, perform three different arm raises to target the shoulders and upper back: T Raise: Lift your arms straight out to the sides until they are parallel to the floor, forming a “T” shape. Y Raise: Lift your arms upward at about a 45° angle from your body to form a “Y” shape. I Raise: Raise your arms straight overhead, close together, forming an “I” shape. Maintain a neutral spine, avoid arching your lower back, and move slowly with control. Focus on squeezing your shoulder blades together and keeping your shoulders down away from your ears.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1606/","author":"WiNNiE","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:8bc4c616-e76b-4291-9074-186ecbbb3cfd','wger-english-2026-09-08',1929,'2026-06-19T18:56:40.268612+02:00','4cf547a37f467c02f86adac0863370b2c39a5e78b257c55012f9837376ca11c4','{"name":"Assisted Pull-Up","instructions":"The Assisted Pull-Up is a compound vertical pulling exercise performed on a machine with a counterweight platform or by using resistance bands. It mimics the mechanics of a standard pull-up but reduces the total weight you have to lift, making it an excellent tool for building functional strength and perfecting your technique.","equipment":["Resistance band"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1929/","author":"amaesc","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:4037fc14-d7a9-4901-8341-6538e415adc4','wger-english-2026-09-08',1219,'2026-06-19T18:50:27.445360+02:00','9c7230d211622ad8c3d51e814f7262e52fff482cfbacb645a3adee633785196d','{"name":"Australian pull-ups","instructions":"Lie down under a high bar or suspension bar, positioned at an appropriate height. Position yourself on your back under the bar, gripping the bar with a supinated grip (palms facing you). Adjust your position so that your body is aligned straight from head to toe. Arms should be fully extended, shoulders stabilized, and legs aligned with the rest of the body. Bend your elbows and pull your chest towards the bar, contracting your back muscles. Imagine you''re trying to bring your shoulder blades together. Hold the contraction at the top of the movement for a moment to maximize muscle activation. Slowly return to the starting position, extending your elbows.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1219/","author":"PaukOne","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:17593b54-1e4e-49d7-8f9f-3a706823a4c5','wger-english-2026-09-08',1263,'2026-06-19T18:51:08.570501+02:00','85bcf46092497f6a6f5537d62932393d3ba01719919a27618d53520d290d1b3b','{"name":"Back bridge","instructions":"Lie on the floor with your back resting on the floor and your legs bent, feet flat on the floor, leaving about 20 cm between your feet and your buttocks. Your hands remain flat on the floor, pressed against your ears, with your fingers pointing toward your toes. Your elbows are bent and pointing toward the ceiling. This is the starting position. Now push your hips as high as you can, raising your body off the floor, and continue pushing through your hands, extending your elbows and knees, until your back is fully arched (lumbar bridge). Your head also comes off the floor and should be level with your elbows, looking back. This is the final position. The descent should be slow and controlled. Your spine should be in a convex curve. It''s not good to lift your back off the floor; it should remain straight. It should be well rounded. You''ll also notice a feeling of increased oxygenation in your back. After lifting off the floor, your hips should be very high, even above the level of your head. Your arms and legs should remain straight. It seems easy, but it requires a good level of flexibility. Breathing should be deep. This posture stretches the rib cage and puts pressure on the diaphragm. If the posture is performed correctly, breathing will be perfect. Never hold your breath during the exercise.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1263/","author":"cynomops","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:d301d901-a2c6-4916-b09e-07ab7a3c8519','wger-english-2026-09-08',1092,'2026-06-19T18:50:55.664340+02:00','750959e0b7a59972824d99a7c945ef0406b09f47f45907d52b61ecdee203e4c2','{"name":"Bag training","instructions":"Bag training improves muscle definition of: deltoids; rear deltoids; triceps; biceps, as well as being a great cardio exercise","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1092/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:a1e8759d-72b9-422f-87a8-9d316fa18498','wger-english-2026-09-08',1525,'2026-06-19T18:53:48.303535+02:00','dc66e22ad2b9c5795535760955e635c600aaba8b2a355e6409bde12d1843e2c4','{"name":"Ball Slams","instructions":"Stand with your feet about shoulder-width apart, your knees and hips slightly bent, holding the ball in both hands at chest height. Engage your core, and keep a good posture. Extend your knees and drive your hips forward while simultaneously lifting the ball. Aim for being as tall as possible, the ball overhead, arms up, hips slightly forward, and on your toes from the force of your drive. Use your core and arms to slam the medicine ball straight down between your feet with as much force as possible. Press your hips back and bend your knees to further power the slam. Exhale as you slam the ball down. Squat down to pick up the ball from the floor, then immediately move into the next slam by repeating the movement. Repeat for reps or time.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1525/","author":"flanny","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:83650b79-add8-4846-b114-b4f28d96495a','wger-english-2026-09-08',1826,'2026-06-19T18:55:37.748674+02:00','75b9777db06f9c479b4aa3a923157322b1544444357c06bdf30e5bc729cd6e97','{"name":"Band pull-apart with external rotation","instructions":"Stand tall with your feet shoulder-width apart, chest out, and shoulders back. Hold the resistance band with both hands, palms facing up or facing each other, depending on the band type. Bend your elbows at a 90-degree angle and glue your upper arms to your sides. The band should have some tension in the starting position, with your hands closer together in front of your stomach. Rotate Outward: While keeping your elbows tucked into your sides, slowly move your hands away from each other, stretching the band. Squeeze: Squeeze your shoulder blades together and down as you rotate your hands outward. Range of Motion: Rotate your hands as far outward as you comfortably can without allowing your elbows to leave your sides. Hold: Hold the end position for 1–2 seconds to maximize muscle engagement. Return: Slowly and with control, bring your hands back to the starting position.","equipment":["Resistance band"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1826/","author":"beagle","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:f18eb684-9a9b-4566-9771-e22a87d536b1','wger-english-2026-09-08',1380,'2026-07-23T12:08:38.479485+02:00','da8ed8f4f4d9603e659007b0f8f4e0ff60f6155466eec2332af69be9acb4c3c1','{"name":"Band pull-aparts","instructions":"Hold the band with your arms extended in front of you at shoulder height. Keep your elbows slightly bent but fixed throughout the movement. Pull the band apart by spreading your arms until the band touches or comes close to your chest. Slowly bring your arms back to the starting position, controlling the tension on the band.","equipment":["Resistance band"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1380/","author":"schwolfar","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:3096b34e-1781-4f99-8187-d9acac8e712b','wger-english-2026-09-08',2494,'2026-08-10T02:41:38.939513+02:00','d6bded24c71cae7f331742d9dd3a1da8d22f0d700605001b71d38d6a2f1833d4','{"name":"Band Terminal Knee extension","instructions":"This is an end range strengthening exercise for the knee extensors. Start by looping a band around the back of one knee and anchoring the other end to a stable surface in front of you. Stand in a split stance with the banded knee bent and placed as the front leg. Straighten the knee to pull against the bands resistance and maintain a contraction in your quadriceps for up to 5 seconds before releasing.","equipment":["Resistance band"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2494/","author":"Rehab Hero","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:8cc84753-e638-4c43-91c6-51c097813ca4','wger-english-2026-09-08',1842,'2026-06-19T18:56:02.174763+02:00','a46ad8c6f8fc93705ecdf815951cbcc02de2ed2a36461878154bb4349e0c75c9','{"name":"Banded Clamshell","instructions":"Position Side plank with the elbow and the forearm on the ground and the legs slightly bent. Stretch a doubled-up resistance band between your thighs, just above the knee. Execution Lift your upper knee while keeping your feet close together, like a “shell opening,” then slowly return to the starting position. Keep your core stable and your hips aligned.","equipment":["Resistance band"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1842/","author":"Croak6728","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:add364ed-4444-4752-9a22-d85d58199fe5','wger-english-2026-09-08',1877,'2026-06-19T18:55:52.550206+02:00','84b678eeb9148809385550119437e8497de7efc1a713fab9180de4d4c0671c8a','{"name":"Banded Scapular Retraction","instructions":"Attach one end of resistance band to wall/upright/... at shoulder height. Insert arm into the loop, at the tricep. Step back until band is pulled straight. Pull back elbow and shoulder against the resistance of the band.","equipment":["Resistance band"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1877/","author":"hurr99","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:a6bced3c-72f5-42a3-9438-5569d46f49fd','wger-english-2026-09-08',41,'2026-06-19T18:48:33.197325+02:00','dbba5989447a6c36e1cba5a40925919d9484210e5c0bca88b76b9c945ec7e1fd','{"name":"Barbell Ab Rollout","instructions":"Place a barbell on the floor at your feet. Bending at the waist, grip the barbell with a shoulder with overhand grip. With a slow controlled motion, roll the bar out so that your back is straight. Roll back up raising your hips and butt as you return to the starting position.","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/41/","author":"sevae","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:e9e7372c-b5c1-45d9-ae5c-b1aa0fc2e2ce','wger-english-2026-09-08',1638,'2026-06-19T18:48:52.166318+02:00','89a52dc505a6310c9c0ef75b37b4b0dcee0219b0455f39994582f228291d4fdd','{"name":"Barbell Clean and press","instructions":"This exercise involves lifting a barbell from the ground to the shoulders, then pressing it overhead. It is a compound movement that targets multiple muscle groups, including the legs, back, shoulders, and arms. It is often used in strength and conditioning programs to improve overall power and athleticism.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1638/","author":"Rottekongen","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:5d0e0a8b-1940-4034-b4ae-b965859f1ff0','wger-english-2026-09-08',1801,'2026-06-19T18:57:50.216398+02:00','1fcd419eaf7cb0987b2325e4cd5d346bc1dd6afec8411100f0bbd8ffa3239c94','{"name":"Barbell Full Squat","instructions":"The barbell full squat is a compound exercise that targets multiple muscle groups in the lower body, including the quadriceps, hamstrings, and glutes. Proper form is crucial for maximizing results and preventing injuries during the barbell full squat. This includes maintaining a shoulder-width stance, creating whole body tension, controlling your descent, and maintaining proper depth and knee positioning. Assistance moves such as the front squat, goblet squat, split squat, and Bulgarian split squat can help improve your performance in the barbell full squat by targeting specific muscle groups and improving overall technique. To achieve new personal records in your back squat, gradually increase weight over time, vary rep ranges and sets to stimulate muscle growth, and prioritize rest and recovery between training sessions.","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1801/","author":"fabrice","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:04e7d7e4-f8d2-406d-97df-3df3bceec22c','wger-english-2026-09-08',46,'2026-06-19T18:56:45.225252+02:00','fcdb756b7762cb1b281b1e972c6a464ec4982c412e62248598146daf52ae8353','{"name":"Barbell Lunges Standing","instructions":"Put barbell on the back of your shoulders. Stand upright, then take the first step forward. Step should bring you forward so that your supporting legs knee can touch the floor. Then stand back up and repeat with the other leg. Remember to keep good posture.","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/46/","author":"Mikko Ruohola","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:67c26c9b-32f3-4b8b-b13a-4d8be4803975','wger-english-2026-09-08',48,'2026-06-19T18:56:45.911487+02:00','52f34a41c239da897159b0d6e9d33b759d0b8e2f1e19ffa00543f94cd4661746','{"name":"Barbell Reverse Wrist Curl","instructions":"Sitting on a bench, grab a barbell with your palms facing down and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees. Curl your knuckles towards your face, lifting the barbell. Pause for a moment in the top position, then slowly return the barbell to the starting position.","equipment":["Barbell","Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/48/","author":"burenl","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:72129e4f-df97-4869-9561-33a1ba3c9186','wger-english-2026-09-08',1700,'2026-07-23T12:08:23.671169+02:00','20f280003786413eba46f921d1d3831cad4faedbdffa45adff16fd3b4081d4b2','{"name":"Barbell Romanian Deadlift (RDL)","instructions":"Execution Hinge at the hips: Push your hips backward , keeping a slight bend in the knees (soft knees). Lower the barbell along the front of your thighs/shins while maintaining a neutral spine . Keep the bar close to your body .","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1700/","author":"daiben","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:6ce25688-ae91-4dc7-9b17-0b66a47151fa','wger-english-2026-09-08',1698,'2026-06-19T19:53:55.770660+03:00','31672cbbf097f30829906f0e6c6012a7ffbc27ebf3c06ac7c353b01f72c82d4c','{"name":"Barbell Row (Overhand)","instructions":"Execution Starting position: Hold the barbell with arms fully extended toward the floor. Maintain tension in your lats and back muscles.","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1698/","author":"daiben","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:3c2b5e2d-bd9d-43e8-8b5f-e6363331faa1','wger-english-2026-09-08',1699,'2026-06-19T18:53:57.125874+02:00','a3a38903af132063db92ac46b7c3c7a98b6392be70b21662ba1bc103f8265b5e','{"name":"Barbell Row (Underhand)","instructions":"Execution Starting position: Hold the barbell with arms fully extended toward the floor. Maintain tension in your lats and back muscles.","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1699/","author":"daiben","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:13234b53-ea0c-41f1-9069-776865ea8eff','wger-english-2026-09-08',50,'2026-06-19T18:46:16.135119+02:00','b0cb0c460ac34677187fe798e7a9ff7c3a389a722f356664a827aed7de5120a0','{"name":"Barbell Triceps Extension","instructions":"Position barbell overhead with narrow overhand grip. Lower forearm behind upper arm with elbows remaining overhead. Extend forearm overhead. Lower and repeat.","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/50/","author":"sevae","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:cfb6a754-57be-431b-b8d0-d9963120bd5a','wger-english-2026-09-08',51,'2026-07-23T12:08:23.213596+02:00','14f3fed1a0243084b728abef66896023f986383c2959f6777c62bf84db823da9','{"name":"Barbell Wrist Curl","instructions":"Sitting on a bench, grab a barbell with your palms facing up and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees. Perform the movement by curling your palms and wrists towards your face. Pause for a moment in the top position, then slowly return the barbell to the starting position.","equipment":["Barbell","Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/51/","author":"burenl","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:a5d1f45b-ff07-45d7-a699-a654f9328934','wger-english-2026-09-08',1524,'2026-06-19T18:53:46.934654+02:00','65a31750c85d7f0ba6b19806dc94c276d65653547d32f0aa5a1d255cdad07668','{"name":"Battle Ropes","instructions":"Hold the ends of the rope at arm''s length in front of your hips with your hands shoulder-width apart. Brace your core and begin alternately raising and lowering each arm explosively. Keep alternating arms for three to four sets of 1 to 2 minutes.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1524/","author":"flanny","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b4dc15da-4d4d-4a93-a30a-74aaf99192ff','wger-english-2026-09-08',1687,'2026-06-19T18:52:10.941148+02:00','5f909a8c96b16d6d785dcd05ca38c05316d8754ed6dadc85e553223980210577','{"name":"Bear crawl pull through","instructions":"Place a dumbbell at around hip level and assume a bear crawl position. Push the knees off the floor and hold. With the opposite hand reach for the dumbbell and pull it to the other side. Place your hand back on the floor and repeat with your other hand.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1687/","author":"meldun","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b7267f90-8706-442b-b918-507e16092b8e','wger-english-2026-09-08',57,'2026-06-19T18:42:47.450431+02:00','7a4729af9b62ba6443b99e3d72b323cf71a37868a3684ca1141b92874ff7bade','{"name":"Bear Walk 2","instructions":"-Rest your weight on your palms and the balls of your feet, not dissimilar to normal pushup position -Move by stepping with your R palm and L foot, then your L palm and R foot. Basically, walk like a lumbering bear. -Move as fast as you can. Measure your reps/sets in either distance (i.e. 40 yards) or time (i.e. 45 seconds) -Works your Pecs, Deltoids, Triceps, Traps, Lats, Abs and Lower Back, Hip Flexors, Quads, Glutes and Calves","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/57/","author":"nate303303","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:57018827-f344-4627-88e5-03e4f2f49859','wger-english-2026-09-08',1807,'2026-07-23T12:36:50.053346+02:00','4672789231d8c6e8f19062c2a4143c7d89242253be46b6cd783046a9ceb00133','{"name":"Behind the Back Cable Lateral Raise","instructions":"Lateral raises have long been a staple for building capped delts, and lifters use everything from dumbbells and bands to machines and single-arm variations to make them grow.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1807/","author":"LEBRERO","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:fbeb1fd5-d259-4a85-a993-03569d8146dc','wger-english-2026-09-08',1320,'2026-06-19T18:51:43.136250+02:00','5374179b4f7613eebf8279ef91dd610a48d449ea363c8bee62b2c5840efc73d0','{"name":"Bench Dips On Floor HD","instructions":"Triceps dips on floor are a compound exercise as they worked multiple muscle groups simultaneously. Although this bodyweight exercise mainly targets the triceps, it also hits your chest and front of your shoulder. Triceps dips on floor are one of the most effective exercises to increase arm strength and also build lean muscle in your upper arms. Triceps dips on floor are a closed kinetic chain exercise and express that you do the movements around a fixed point. It increases compression force on your joints thereby improving stability.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1320/","author":"hektkaso","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:3717d144-7815-4a97-9a56-956fb889c996','wger-english-2026-09-08',73,'2026-06-19T18:46:21.803261+02:00','16fc14e19fc635fcf9bf6166624edbc00d05c2abd72c2215bef3ba13c15090e8','{"name":"Bench Press","instructions":"Lay down on a bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up. If you train with a high weight it is advisable to have a spotter that can help you up if you can''t lift the weight on your own. With the width of the grip you can also control which part of the chest is trained more: wide grip: outer chest muscles narrow grip: inner chest muscles and triceps","equipment":["Barbell","Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/73/","author":"sistab2","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:20d8df5a-c9d6-4c69-bdf2-d97af68ac83f','wger-english-2026-09-08',2536,'2026-09-01T09:12:51.593088+02:00','c380f80ee9158147915b62ffafe1ec217fa80242f48b549dd67d3176f3c5235c','{"name":"Bench Press Isometric","instructions":"A bench press isometric hold is a static strength exercise where you pause and hold a barbell or dumbbells either at your chest, mid-press, or at lockout without moving for a set time","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2536/","author":"HexoctusEngineering","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:3db63138-a047-4a4d-b616-1a0b7dfca105','wger-english-2026-09-08',76,'2026-07-02T16:14:26.402383+02:00','8a6147708db7af4a43aa1f2cdd1f65244bddfdefe4caffed78de83b276f450c6','{"name":"Bench Press Narrow Grip","instructions":"Setup: Lie flat on the bench and grip the bar at shoulder-width (closer than a standard bench press). Descent: Lower the bar with control to your lower chest. Form: Keep your elbows tucked in tight against your torso—do not let them flare out. Ascent: Press the bar straight back up, squeezing your triceps at the top.","equipment":["Barbell","Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/76/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:28321cf3-70e6-48a4-ade1-d11382180cb3','wger-english-2026-09-08',75,'2026-07-02T16:44:41.508287+02:00','76db4eb3f066659585b2cb43faa9821011c17b39ba14c856c1106ac83fcfa306','{"name":"Benchpress Dumbbells","instructions":"Setup and Starting Position: Sit at the end of a flat bench with a dumbbell resting vertically against each thigh. Carefully lean back while driving the dumbbells toward your chest with your knees. The “Leg Drive” and Posture: Plant your feet firmly on the floor. Retract your shoulder blades (press them together against the bench) and maintain a slight natural lumbar curve. Starting Position: Push the dumbbells toward the ceiling. Your wrists should be aligned with your elbows. Rotate the dumbbells slightly inward (about 45 degrees) so that your elbows do not splay out too far to the sides, thereby protecting your shoulders. Eccentric Phase (Lowering): Lower the dumbbells in a controlled manner toward the sides of your chest. Your elbows should lower at an angle of about 45–60 degrees relative to your body. Feel the stretch in the lower part of your chest. Concentric Phase (Lift): Push the weight upward in a slight arc (toward the center), without letting the dumbbells collide at the top or fully locking out your elbows to maintain muscle tension. Exhale as you lift. Translated with DeepL.com (free version)","equipment":["Bench","Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/75/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:01271ea0-088c-4e2b-95ad-876af7127057','wger-english-2026-09-08',79,'2026-06-19T18:48:34.538789+02:00','657ed79b7a9d88db52dc24b23604ca4c5e54cda125e9d74a1a605eb85c293257','{"name":"Bent High Pulls","instructions":"Bend over slightly while holding two dumbbells. Pull the dumbbells up to your chest, keeping your elbows as high as you can.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/79/","author":"lakerbeezel","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:94a5c406-7bcd-47f3-9687-bdf92a763932','wger-english-2026-09-08',81,'2026-06-19T18:46:18.172373+02:00','1fc3975825e0d13fcc48dec23a19c3748274dc0b3f07e647cb1e3f62c2bed481','{"name":"Bent Over Dumbbell Rows","instructions":"With dumbbells in hand, bend at the hip until hands hang just below the knees (similar to straight-legged-deadlift starting position). Keep upper body angle constant while contracting your lats to pull you ellbows back pinching the shoulder blades at the top. Try not to stand up with every rep, check hands go below knees on every rep.","equipment":["Bench","Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/81/","author":"sebk","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:6f79b381-98a4-40d5-8a45-3bb0558be6fe','wger-english-2026-09-08',82,'2026-06-19T18:46:19.206526+02:00','f26575a3ef5a01b551d4612cc95058e32a49270d7c090c9e3a8faac73dd6f2d0','{"name":"Bent-over Lateral Raises","instructions":"Sit on bench while holding weights. Bend forward as far as possible, with arms slightly bent at the elbow. Perform a lateral raise while maintaining the bend in your elbow.","equipment":["Bench","Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/82/","author":"apeschel","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:f3f4e9c5-9bf6-43f6-a2cf-798507a50293','wger-english-2026-09-08',1082,'2026-06-19T18:49:20.604083+02:00','d37972eec50e2af1c9ac8332fcfbd43c018bd20619c295d2d56fcdb1ee6ad555','{"name":"Bent over row to external rotation","instructions":"Starting position: Stand behind a chair or in front of a table. Bend at the waist to put your forehead on the chair''s headrest or table, keeping your back straight. Your arms should be hanging straight down, pointed at the floor. Steps: Bring your elbows up to shoulder height. Your forearms should be pointing down, perpendicular to your biceps. Your biceps should be at the same height as your back and perpendicular to your spine. Hold for a bit. Rotate at your elbows to bring your hands as far up as you can. Hold for a bit. Rotate at your elbows back to the previous position. Bring your arms down to the original position. Repeat.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1082/","author":"tinman","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:4af6dbd9-8991-484b-9810-68f117c21edf','wger-english-2026-09-08',83,'2026-06-19T18:46:17.668412+02:00','bdf2e832c633a27a52779d586b7ce90de02bcb541d5248cadda9699cb6ae19bb','{"name":"Bent Over Rowing","instructions":"Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position. Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause. Then inhale and slowly lower the barbell back to the starting position. Repeat for the recommended amount of repetitions.","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/83/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:2f0ddf9a-f520-4c55-8883-f0d4a789f481','wger-english-2026-09-08',84,'2026-06-19T18:49:45.219028+02:00','840eb15b2f194836bc400f72d185fca647a15eeaf3fa5fe3a5035dbcfbe2532e','{"name":"Bent Over Rowing Reverse","instructions":"The same as regular rowing, but holding a reversed grip (your palms pointing forwards): Grab the barbell with a wide grIp (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest''s out during the whole exercise. Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don''t swing with your body and keep your arms next to your body.","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/84/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:8bb42000-834f-48ab-af5c-0c31d94e0181','wger-english-2026-09-08',1280,'2026-06-19T18:51:13.331083+02:00','2d7fd4cb97eab0e30d85b8f56fd2456aa6f7fb1ecde3de6211807024c8bc09e5','{"name":"Biceps Close Grip Pull Down","instructions":"On a lat pull down machine, hold the bar keeping your hands relatively close. Use an underhand grip (I.E.: the back of your hand must be facing the machine). Then pull down the bar in a straight line towards the ground. Make sure your biceps are the main drivers of the motion. You will probably feel your shoulders and lats working, but make sure your biceps are working more.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1280/","author":"daniel.escada","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:e68f6d51-fe02-4175-b277-dec0c1521f36','wger-english-2026-09-08',1424,'2026-06-19T18:52:33.112552+02:00','9576548cd1dc3a308fcf136f5f16c0082bf90139622478d3805f3bf215ef5883','{"name":"Biceps Curl Machine","instructions":"The biceps curl machine is designed to isolate the biceps muscles and provide a controlled range of motion. Sit on the machine with your back against the pad and adjust the seat so your arms are aligned with the machine''s handles or pads. Grip the handles firmly, keeping your elbows fixed in place, and curl the handles upward by contracting your biceps. Slowly lower the handles to the starting position, maintaining control throughout the movement.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1424/","author":"hpmbala@gmail.com","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:bcb7020c-8678-496d-8f4d-aad0e233a5bd','wger-english-2026-09-08',95,'2026-07-23T12:36:13.168665+02:00','0a603ffa318f51bf69ad351350427080eba6652ca4e95e60a57b48ca41ceb750','{"name":"Biceps Curl With Cable","instructions":"Stand around 30 - 40cm away from the cable, the feet are firmly on the floor. Take the bar and lift the weight with a fast movements. Lower the weight as with the dumbbell curls slowly and controlled.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/95/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:7b99a081-6b1a-4aa5-b86a-5a935d083a35','wger-english-2026-09-08',91,'2026-06-19T18:46:19.725861+02:00','aaffc533e324ad51b9d5c13c832c8f6bd40c27740824f5a81c7a5ce4626d599e','{"name":"Biceps Curls With Barbell","instructions":"Hold the Barbell shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement. Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/91/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:1ae6a28d-10e7-4ecf-af4f-905f8193e2c6','wger-english-2026-09-08',92,'2026-06-19T19:55:06.817496+02:00','284b034343611a3f532ebb40abcc3e3d442a071fe002d947485339fbe93904ec','{"name":"Biceps Curls With Dumbbell","instructions":"Hold two dumbbells, the arms are streched, the hands are on your side, the palms face inwards. Bend the arms and bring the weight with a fast movement up. At the same time, rotate your arms by 90 degrees at the very beginning of the movement. At the highest point, rotate a little the weights further outwards. Without a pause, bring them down, slowly. Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/92/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:42227131-9b1e-4220-b082-c523f0651057','wger-english-2026-09-08',94,'2026-06-19T18:46:18.692960+02:00','9ea565beb2d7aa08e184030af716388714e7e3f67ebfbdf99eb1e8dce31e6a99','{"name":"Biceps Curls With SZ-bar","instructions":"Hold the SZ-bar shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement. Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).","equipment":["SZ-Bar"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/94/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:596b9d2d-0f01-41a0-97e1-1839ffdb824d','wger-english-2026-09-08',958,'2026-07-23T12:08:27.198492+02:00','dc09523f58553cd52089e6f500d2b2fb6c6e11366524a918858eca8f94004aba','{"name":"Biceps with TRX","instructions":"Grab the handles of the TRX straps, lean your body back, arms and legs extended, with your body positioned in a single straight line. (This is an arm exercise, not an abdominal one.)","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/958/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:fcf5039b-7784-4f82-830a-b213b597a646','wger-english-2026-09-08',1412,'2026-06-19T18:52:30.992193+02:00','58bd81bd53e33132c190f3b0dce22194833cff800464f0de5fb04098922c4ccd','{"name":"bicycle crunches","instructions":"Bicycle crunches are a core exercise performed on the floor. Lie on your back with your hands behind your head and legs extended. Lift your shoulders off the ground, bring one knee toward your chest, and twist your torso so your opposite elbow meets the knee. Alternate sides in a pedaling motion, ensuring controlled movements and engaging your core throughout the exercise.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1412/","author":"hpmbala@gmail.com","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:6349365e-e901-4280-a1b7-65734986f47d','wger-english-2026-09-08',1572,'2026-06-19T18:54:14.941101+02:00','e953ee50da205d461aa88784c2902547c13f1c80ffa3836c4e06d5671394f7a4','{"name":"Bird Dog","instructions":"The Bird Dog is a core stability exercise that enhances balance, coordination, and spinal alignment. It’s a low-impact movement ideal for strengthening the posterior chain and improving overall functional control. Begin on all fours with hands under shoulders and knees under hips, keeping your spine neutral. Extend your right arm forward and left leg backward simultaneously, keeping hips square. Pause briefly at full extension while engaging your core and glutes. Return to the starting position and repeat on the opposite side","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1572/","author":"Settebello","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:6d45afed-05c4-42a2-994b-5ef62a9d0aed','wger-english-2026-09-08',2508,'2026-08-10T07:11:40.408389+02:00','b1b18f9bcee0b8682609bd50ce4dd8d8169b272da85047ffe55b4cc61262d195','{"name":"Bird Dog (Core L1)","instructions":"Vasco custom bird dog - foundational contralateral limb coordination and lumbar stability. Teaches hip dissociation from spine, glute activation, and scapular control.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2508/","author":"Vasco Custom","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:da6ab4d8-edd2-428d-b194-fb15948d3fd5','wger-english-2026-09-08',1483,'2026-06-19T18:53:13.272703+02:00','23e568fee38db5a544ccd13b455636bccbc5b77f6f972bb3418eb734423edb7f','{"name":"Bizeps Curls Trifecta","instructions":"This exercise is a mixture of three different curls: the Supinated Cross Body Curl, the Pronated Cross Body Curl and the No Money Curl. You alternate between three curl variations that each accomplish different goals, and you’ll keep the set going beyond the usual 8-12 rep range which gives us that intensity. For the Supinated Cross Body Curl, supinate the forearm with palms facing toward the ceiling and forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder. For the Pronated Cross Body Curl, pronate the forearm with palms facing toward the floor (pronated grip or overhand grip) and forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder. For the No Money Curl, you’ll curl the dumbbell as you outwardly rotate the shoulder. Lift the inner-facing weight of the dumbbell towards your outer side of the shoulder.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1483/","author":"Moffi","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:64ebb7a5-15ec-48dd-8f82-47cdb022f215','wger-english-2026-09-08',1475,'2026-06-19T18:53:03.162768+02:00','36d8fe617a9ab9777ec7470f6213714097c98b68f59edda8f51b1296b0023232','{"name":"Black Widow Knee Slides","instructions":"In this bottom-up rotation exercise movement, you’ll cross your knee over and drive it into that opposite elbow. Start in high plank position (or tabletop position) with hands directly beneath your shoulders. Lift the left knee toward the right arm and slide it up the forearm to get more of that posterior pelvic tilt and engagement of the abdominal muscles. Then do the opposite side, bringing your right knee toward your left hand.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1475/","author":"Moffi","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:24f988e7-51eb-44f5-92f2-d4e0199c2269','wger-english-2026-09-08',1630,'2026-07-23T12:08:32.796007+02:00','a0de6d235496b34035dbfa0f708cbb3262da7db9d9b7ca285e85eb8242fac82b','{"name":"Blaze","instructions":"BLAZE is a full-body HIIT workout. Designed to supercharge your cardio fitness and strength. Delivered in its own purpose-built studio, BLAZE is a unique mix of martial arts, intense cardio and strength training.","equipment":["Bench","Dumbbell","Kettlebell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1630/","author":"ricwheatley","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:c4b2ed05-38d5-47fc-9ad1-c23f09fddd61','wger-english-2026-09-08',2482,'2026-07-22T07:50:04.955193+02:00','54931268a2e8e83dba12e7a2312b4e72864430f778f8d329e234d45088f32347','{"name":"Bobbing Exhale Drill","instructions":"Stand in chest-deep water. Take a breath, submerge your face fully, and exhale slowly and completely through your nose and/or mouth the whole time you''re underwater — a gentle humming sound can help keep the exhale steady and controlled. Once you''re empty of air, lift your head, take a fresh breath, and go back under. Repeat continuously. The goal is training your body that all your exhaling happens underwater, so all you need to do at the surface is inhale.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2482/","author":"Imported from swim plan","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:d551f24d-44fe-4761-9448-edf14d627827','wger-english-2026-09-08',112,'2026-07-23T12:24:54.719309+02:00','d8b16b1ac5d157a18d0b618c534db3dbb11dce677fa9957e9380d386a5b0118e','{"name":"Body-Ups","instructions":"Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position. Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement. Slowly lower your forearms back to the ground by allowing the elbows to flex. Repeat as needed.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/112/","author":"cal.zabel","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:a94623fc-518f-4a74-947b-febd086264bf','wger-english-2026-09-08',1608,'2026-06-19T18:54:43.741006+02:00','7c45320107154e9602c7a40119dde7b7883e0b380d924aa9cc8083a5bbf16a52','{"name":"Bodyweight Biceps Curl","instructions":"Set up under a straight bar (around waist or chest height). Grip the bar with your palms facing you (supinated grip), hands about shoulder-width apart. Lean back with straight arms so that your body is at an angle to the ground. Keeping your elbows high and close to the bar, pull your upper body toward the bar by flexing your elbows, similar to a biceps curl. Lower yourself back down in a controlled manner. Keep your core tight and movement slow to maximize tension on the biceps.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1608/","author":"tenebrizz","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:f9a0a918-3c0c-464e-bbba-1bd309d4a519','wger-english-2026-09-08',1324,'2026-06-19T18:51:44.496483+02:00','6a26aa7d46f6f36dde5b33b1e87046e0d07d8fabd2117cd03de57dfe59e5340d','{"name":"Bodyweight lunge HD","instructions":"Bodyweight lunges are an effective calisthenic exercise for strengthening the lower body, improving balance and stability, and developing functional strength. They are a popular choice for bodyweight workouts, home workouts, and can also be included as part of a larger strength training routine.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1324/","author":"hektkaso","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:edc3f6b7-96b0-4967-90d7-bba9d7d442cb','wger-english-2026-09-08',1312,'2026-06-19T18:52:02.129678+02:00','d955804ac8306b272fad7b8c08555b75d834326dd703f4d0f447fd982a1df214','{"name":"Bodyweight Squat HD","instructions":"Squat is a type of bodyweight exercise. It is one of the most popular exercises for strength and muscle growth. Squat is particularly effective for focusing on the muscles of the leg and hips. Squat are an easy exercise for beginners to do. It can help strengthen leg muscles, tighten hip muscles and burn calories to lose weight. It tightens the butt and legs. Squats are very effective for firming and strengthening your legs by acting on the gluteus,hip flexors, quadriceps, hamstrings and inner thigh muscles. Also, bodyweight squats can help shape your glutes and butt.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1312/","author":"hektkaso","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:002c6a4f-28ac-4b07-8e94-053e5b05d52b','wger-english-2026-09-08',1373,'2026-04-15T22:23:56.393991+02:00','aafe0539483c98f356398840343565a8c202c9c6d50eeba7a728272dc97bd0e0','{"name":"box jumps","instructions":"Jump from a standing position onto the box, stretch your body, then step down again (do not jump)","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1373/","author":"tekknokrat@gmx.de","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:151434a5-c046-459f-a3a9-c3125075856f','wger-english-2026-09-08',977,'2026-07-23T12:08:28.395702+02:00','9cfb3630d839069ab2be4de391578fc37e94378ae9fd07c20e94ac064903aeca','{"name":"Box squat","instructions":"Set up the box: Position the box behind you, about 3 feet from a squat rack if you''re using a barbell. Choose a height that allows you to squat down and gently tap your glutes on the box with your back straight. Stand with proper form: Stand with your feet shoulder-width apart, toes pointed slightly outward. Engage your core and keep your back neutral. If using a barbell, rack it at shoulder height. Lower down: Sit back as if going to sit on a chair, bending your knees and lowering your hips towards the box. Keep your core tight and back straight throughout the movement. Controlled descent: Descend in a controlled manner until your glutes gently touch the box. Don''t plop down. Pause and press up: Briefly pause at the bottom with your back straight and core engaged. Then, press through your heels to drive yourself back up to the starting position. Improvements in coordination, balance and endurance, toning of the leg and buttock muscles and an overall increase in bone density eliminating the risk of osteoporosis.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/977/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:8c6428f3-d41d-4ffc-8444-bb9b823bc42b','wger-english-2026-09-08',124,'2026-06-19T18:56:51.432954+02:00','229cb758fc118df039a065559050512380957faa0e2b245a3e592281447f5ada','{"name":"Braced Squat","instructions":"Stand with feet slightly wider than shoulder-width apart, while standing as tall as you can. Grab a weight plate and hold it out in front of your body with arms straight out. Keep your core tight and stand with a natural arch in your back. Now, push hips back and bend knees down into a squat as far as you can. Hold for a few moments and bring yourself back up to the starting position.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/124/","author":"sevae","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:a94c635d-096c-45a8-a68c-64941d0b6ba4','wger-english-2026-09-08',1577,'2026-07-23T12:25:26.883450+02:00','b096e558ae8ca6cd05258678afe143fead8d361bec7180fc5c2c7ad8efdedea4','{"name":"Bretzel stretch","instructions":"How to Perform the Bretzel Stretch Starting Position: Lie on your back on a flat surface, such as a mat. Bend your knees and place your feet flat on the ground. Leg Positioning: Lift your right leg and cross it over your left leg, placing your right foot on the outside of your left knee. Your left leg should remain flat on the ground. Arm Positioning: Extend your left arm out to the side at shoulder height, keeping it straight. Use your right hand to gently pull your right knee towards the floor on the left side of your body. Stretching: As you pull your knee down, try to keep your left shoulder flat on the ground. You should feel a stretch in your hip, lower back, and possibly your chest. Hold the Position: Maintain this position for 20-30 seconds, breathing deeply and relaxing into the stretch. Switch sides and repeat the process.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1577/","author":"mountain.potato","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:a6d880e5-bdbe-408f-b762-3b41c7fff834','wger-english-2026-09-08',1579,'2026-06-19T18:54:22.104389+02:00','f83b78c388366df035c0f12016fc85fdfc5c2c1869bb80530e86c63fe76fb77d','{"name":"Bronco","instructions":"Finess test for rugby.5 x shuttle runs of 20m, 40m, and 60m (20yd, 45yd, 65yd/far 45yd mark) Complete as fast as possible","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1579/","author":"MU5H","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:60d2c34b-43a1-48a3-b43b-160e4c0157f2','wger-english-2026-09-08',1706,'2026-06-19T19:54:06.798695+03:00','818aa5002ebacb0fcf1c13e791af8ad5905a838e69a708549b2917f733241bab','{"name":"Bulgarian Squat with Dumbbells","instructions":"The Bulgarian split squat consists of performing a squat on one leg with the rear foot resting on a raised platform. Elevating your back leg on a bench creates instability and increases the range of motion of the exercise.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1706/","author":"AlucardEvil40","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:3d85bdce-e1a9-48a2-b14d-8032820ebf25','wger-english-2026-09-08',915,'2026-07-02T20:08:44.979820+02:00','d068891b5b2021c2093f9a3f169a5f735b08814d5c5c702e5eee062bf5945d3c','{"name":"Bus Drivers","instructions":"Sitting with a Weight Plate, used as wheel, in both hands; raised slightly below eye level","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/915/","author":"novadani","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:4885c051-154b-4a9b-a0fe-ccb70a652fa4','wger-english-2026-09-08',1710,'2026-06-19T18:54:09.524625+02:00','75c0c4d8d2dcbe731f7a913841661a6966ce3d1a1abac29e13e20f1c238fe7df','{"name":"Butchers Block Stretch","instructions":"Kneel down with the hands together Rest the elbows on a bench in front of you and lower the chest down Keep the elbows bent with good posture and hold","equipment":["Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1710/","author":"Croak6728","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:99449eae-0eae-44ab-a57f-fc094bbdda13','wger-english-2026-09-08',135,'2026-06-19T18:46:27.982120+02:00','812b5f2706b79f63cd75e7fd12b0e4477d1ca4c7b5f305dc56b76e2c3a086cac','{"name":"Butterfly","instructions":"Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/135/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:80ff0a3a-ae45-497d-8c27-2b12e3b6e1b8','wger-english-2026-09-08',137,'2026-06-19T18:46:27.476747+02:00','e5f96cde7d2b2054c0974a40b1f05d38d461fae109ee4fb327ea20446088564a','{"name":"Butterfly Narrow Grip","instructions":"The movement is the same as with a regular butterfly, only that the grip is narrow: Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/137/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:1bb3bbaf-2dc2-4651-95db-71faf5304075','wger-english-2026-09-08',1476,'2026-06-19T18:53:04.512143+02:00','af68e49902a65847070c546e790b85448060e2cc01f4f805edd108a73aa043bb','{"name":"Butterfly Sit Up","instructions":"In this midrange exercise your arm muscles provide you with a little bit of momentum to help to get you off the ground. You also open them up in overhead position which engages the upper back. Start lying with feet flat on the ground, knees at an angle, arms crossed in towards your chest. Using your ab muscles, bring your upper body off the ground as you open your arms into goal post position, then slowly lower yourself back down to return to starting position.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1476/","author":"Moffi","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:df3a6900-55c1-435b-bcde-7510dc229b20','wger-english-2026-09-08',1843,'2026-06-19T18:55:18.279640+02:00','697fedbac72c093843398eae271749baa9cd495091f72c1a38b08e427fdbd345','{"name":"Butterfly Stretch","instructions":"Sit in a prayer position with the soles of your feet gently pressed together. Use your hands to slowly pull your feet inwards towards your groin. Hold for as long as required.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1843/","author":"Croak6728","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:de06856d-109d-4bef-acab-0918028cea36','wger-english-2026-09-08',1908,'2026-04-15T22:23:53.034565+02:00','770e5cd5bc6c3b109d74fd625ceef5643a1f0e519ab9de37fc37e7f4f50d48cc','{"name":"Butterfly Superman","instructions":"Lie on stomach, intertwine fingers behind the head and start raising your head and raise elbows as far as they go.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1908/","author":"cybro","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b2865908-b93e-4507-ada4-a5bb9317566c','wger-english-2026-09-08',1656,'2026-07-23T12:36:39.040307+02:00','78864610ce4d7599ebba2dc97f9a5ad99c1af2903c6621684bcecf7a76013cd0','{"name":"Cable Chest Press - Decline","instructions":"Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight decline and aiming towards the center of your chest.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1656/","author":"Shiladree","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:e22c4320-7753-49c6-b7f7-4be21b025fb6','wger-english-2026-09-08',1660,'2026-07-23T12:36:39.843118+02:00','4e9e595894895ef0b7e2317f5dc9acd22f5fb4f126fa251b2a5dd5901668fcba','{"name":"Cable Chest Press - Incline","instructions":"Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight incline and aiming towards the center of your chest.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1660/","author":"Shiladree","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b1bf02cf-17b2-4bfc-a5b0-4ff7a2768dbb','wger-english-2026-09-08',1109,'2026-07-23T12:36:24.687380+02:00','8c3332aa67054abfe6a4cbbf0315714d83a6746600efc0d8970b604fa341a526','{"name":"Cable Concentration Curl","instructions":"The concentration curl is a classic exercise for building the biceps one arm at a time. It can be performed bent over or kneeling, but is more often performed seated on a bench. It''s great for emphasizing the biceps peak and is often used to finish a biceps workout","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1109/","author":"cshep442","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b16e3e5d-8401-4d2b-919c-15b536f9ec5e','wger-english-2026-09-08',323,'2026-07-23T12:36:16.446300+02:00','4c8a5b2a75971ee703fbfb221064a30a26997435430d2579dcfa901d1bf2b1d2','{"name":"Cable Cross-over","instructions":"Begin with cables at about shoulder height, one in each hand. Take a step forward so that one foot is in front of the other, for stability, and so that there is tension on the cables. Bring hands together in front of you. Try to make your hands overlap (so that the cables cross) a few inches.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/323/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:dc3a2072-abc3-4ef9-b8e6-f5ae6b11bc7f','wger-english-2026-09-08',142,'2026-07-23T12:36:13.573281+02:00','2814260176685e22fb4d1a6cdd73c50e1877b2d4d77df154224e2c1fcde41d7f','{"name":"Cable External Rotation","instructions":"Steps: Start off placing an extension band around a post or in a secure position where it will not release and is at elbow level. Position yourself to the side of the band and with your hand that is opposite of the band, reach out and grab the handle. Bring the band to your chest keeping your elbow bent in a 90 degree angle then slowly rotate your arm in a backhand motion so that the band externally rotates out Continue out as far as possible so that you feel a stretch in your shoulders, hold for a count and then return back to the starting position. Repeat for as many reps and sets as desired.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/142/","author":"lauroernesto","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:ae695660-7cee-4601-8241-edd3e2a6d896','wger-english-2026-09-08',1691,'2026-07-23T12:36:42.294200+02:00','daea2bbbb251dede9767c7f70193996989417b1fea56d99298767907c3ebf6d8','{"name":"Cable Fly Lower Chest","instructions":"Execution Start position: Arms extended out to your sides in a “Y” shape. Feel a stretch in your chest (slight bend in elbows — don’t lock them). Movement: Bring your hands downward and together in front of your lower chest or upper abs , in a smooth arc motion. Squeeze your chest hard at the bottom for 1–2 seconds. Return: Slowly raise your arms back up along the same path until you feel a good stretch in your chest. Maintain control — don’t let the weights pull you back too quickly.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1691/","author":"daiben","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:5b4fb3ec-53a1-4525-a58a-c070798ea86e','wger-english-2026-09-08',1689,'2026-07-23T12:36:41.454264+02:00','50dce2550201fc1d80c27db040d23c78cf8fade74fd2b720bce9c340b4339c3f','{"name":"Cable Fly Middle Chest","instructions":"Execution Start position: Arms extended out to your sides (a big “T” shape), feeling a stretch in your chest. Movement: Bring your hands together in front of your chest in a wide hugging motion . Focus on squeezing your chest at the center. Do not lock your elbows or turn it into a press. Return: Slowly open your arms back to the start, maintaining tension on the chest.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1689/","author":"daiben","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b16a28c4-40bf-42d4-94b3-bf3f56fab743','wger-english-2026-09-08',1690,'2026-07-23T12:36:41.867060+02:00','6fa9923fd67911346b7e20f99d70361a2957c8ad1c2eb507b89da036dddd50ea','{"name":"Cable Fly Upper Chest","instructions":"Execution Start position: Arms down and slightly behind your body, elbows slightly bent. Feel a light stretch across your chest. Movement: Bring your hands upward and together in front of your upper chest — roughly at chin to collarbone level . Use a smooth, controlled motion (avoid jerking). Squeeze your chest at the top for 1–2 seconds. Return: Slowly let your arms move back down and out to the sides, keeping control and tension.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1690/","author":"daiben","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:6e03ecb3-6bfe-4b34-be9d-e5c33e820cc6','wger-english-2026-09-08',1745,'2026-07-23T12:36:47.197968+02:00','2f2945148b66b51f034d1c78ba41d9f0896744ffa29e705c08d23daea9e7e0e9','{"name":"Cable Front Raise with a small bar","instructions":"The Cable Front Raise with a small bar isolates your anterior deltoids (front shoulders) by providing constant tension, requiring you to stand facing away from a low pulley, grab the bar with an overhand grip, and lift it in front of you to shoulder height with slightly bent arms, avoiding swinging and keeping your core tight for controlled movement up and down. Use a light-to-moderate weight, focusing on slow, controlled reps to feel the muscle work, not momentum. How to Perform the Cable Front Raise (Bar) Setup: Attach a small straight bar to a low cable pulley. Set the weight to a light or moderate setting. Starting Position: Stand with your back to the machine, holding the bar with an overhand grip (palms facing down) at hip level, arms extended but not locked. Feet shoulder-width apart, core braced, shoulders back and down. The Lift: Exhale and slowly raise the bar straight up in front of you, keeping a slight bend in your elbows, until your hands reach shoulder height (or slightly below). The Hold: Pause briefly at the top, squeezing your front delts. The Lower: Inhale as you slowly and controllably lower the bar back to the starting position, maintaining tension.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1745/","author":"Tierrasverdes","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:19a9f67b-60f5-4367-9134-b805f3e73956','wger-english-2026-09-08',1131,'2026-07-23T12:36:26.342568+02:00','9ff6873f66d8d427319690e206445ddd13c7334991bf1d0f51257813c3571778','{"name":"Cable glute extension","instructions":"This exercise lets you work the upper, or larger, part of the glutes. For that reason, it should never be missing from your routine of isolated exercises for training the glutes. Stand in front of a cable machine and locate the low pulley. Then attach the ankle strap to work on the low pulley. As for your posture, you should stay upright at all times. Pay special attention to your back to keep it straight and avoid injury. It is advisable to hold on to the machine for better balance. With the leg that is holding the weight of the cable, perform a slow stretch backward without bending the knee.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1131/","author":"Franpol","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:81942f3d-d92c-431c-b9d0-0da12918d1e4','wger-english-2026-09-08',1378,'2026-07-23T12:36:30.445670+02:00','d56f4589c44d0b4e2e5d2ffc1bd491be21f95d2563494d5df76f72ffb0fd4700','{"name":"Cable Lateral Raises (Single Arm)","instructions":"The single arm cable lateral raise is a variation of the lateral raise and an exercise used to build the muscles of the shoulders. Position a cable at the lowest position possible and attach a single handle. Reach across your body and grab the handle with a neutral grip. Keep the elbow slightly bent and pull the handle across your body and raise laterally. Slowly lower the handle back to the starting position under control.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1378/","author":"carlos3c","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:70479b75-0df4-4ac2-a324-4a44b148304c','wger-english-2026-09-08',1457,'2026-07-23T12:36:30.839129+02:00','33e3155d1f33cbf1eb81e14fa53050437493b97b2024f53b3be8a12636830c67','{"name":"Cable Press Around","instructions":"Set the cable pulley at chest height and attach a D-handle bar. Grab the handle with a neutral grip and hold it next to your chest with your elbow fully flexed and tight to your side. Turn away from the pulley so your torso is at 45 degrees. Hold the other side of the functional trainer with your corresponding hand. Assume a staggered stance for better balance. While keeping your chest proud, extend your elbow at 45 degrees across your midline while keeping your arm parallel to the floor. Stop shy of lockout and contract your chest at the top of the range of motion (ROM).","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1457/","author":"Expenses7000","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:821e289e-bd39-4410-b436-6f2a43bc3649','wger-english-2026-09-08',1751,'2026-07-23T12:36:47.683102+02:00','84f62b7c9d6d954bfadc7575841b394547a8b5b953eaee4d462b5fc7cf711f51','{"name":"Cable pull through","instructions":"The Cable Pull Through is a lower-body exercise that targets the glutes and hamstrings using a \"hip hinge\" motion. To perform it, attach a rope to the lowest pulley setting, face away from the machine with the rope between your legs, and step forward to create tension. Keeping your back flat and knees slightly soft, push your hips backward as if trying to close a door behind you until you feel a deep stretch in your hamstrings. To finish the rep, explosively drive your hips forward to return to a standing position, squeezing your glutes hard at the top. It is vital to remember that this is not a squat ; your knees should not bend deeply, and your arms should remain straight and relaxed, acting only as hooks for the rope. This movement provides constant tension on the glutes while placing less stress on the lower back than a traditional deadlift.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1751/","author":"manuher89","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:5d244235-cd56-472a-876e-6e530a899ef2','wger-english-2026-09-08',822,'2026-07-23T12:36:22.670251+02:00','1c4762d9cdfc8f950b9760a143f94136e6d30943d46bb29606faeed7b5459d1e','{"name":"Cable Rear Delt Fly","instructions":"The reverse cable fly, also known as the cable rear delt fly, is a deltoid muscle strengthening and definition exercise. It’s one of the best isolation exercises for your back and posterior deltoid.This workout targets your posterior (back) deltoids while using a range of upper body muscles. Adjust the weight and the pulleys to the right height. You should be able to see the pulleys because they should be above your head. With your right hand, grab the left pulley, and with your left hand, grab the right pulley, crossing them in front of you. This is where you’ll begin your journey. Start the movement by moving your arms back and forth while keeping your arms straight. Pause at the finish of the move for a brief moment before returning the handles to their starting positions.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/822/","author":"cshep442","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:0285f198-36d5-4a77-bb76-5f72e1a4d6c9','wger-english-2026-09-08',1936,'2026-07-23T12:36:52.479787+02:00','588e682d7f61a0ae0392fff67b47d5e91bca46954c201b62cf22699a6c432e22','{"name":"Cable Rear-Delt Fly (single arm)","instructions":"Cable rear delt fly (single arm): Stand sideways to a cable machine with the handle set around shoulder height. With a slight bend in the elbow, pull the handle out and back in a wide arc so the upper arm moves away from the body. Keep your torso still and focus on the rear delt doing the work. Use light to moderate weight and controlled reps.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1936/","author":"Dulive","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:07ded945-de5d-4e77-b13c-17d51a2f0007','wger-english-2026-09-08',1662,'2026-07-23T12:36:40.644134+02:00','a863b81884296016e05b28a2c6413406c00d992db13de8be4331014ce666e4dc','{"name":"Cable Tri Extension - Internal Rotation","instructions":"single arm exercise with cable held at opposite shoulder with elbow bent. Turn towards the cable, and the straighten the elbow across the body.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1662/","author":"Shiladree","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:1ea73578-08a5-4f3e-9255-3c58b29b170d','wger-english-2026-09-08',1509,'2026-07-23T12:36:35.793372+02:00','2df8252894d3f9d0649e0ac38f0afea30412e670fe5f77deb94fda850a5eb082','{"name":"Cable Tricep Kickback","instructions":"Grab onto the handle, and pull your elbow up and back slightly above your torso. Keep your upper arm to be parallel to the ground for the duration of the set","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1509/","author":"Expenses7000","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:5aee8ae1-2752-4868-af62-e3c79954d811','wger-english-2026-09-08',1661,'2026-07-23T12:36:40.242119+02:00','abf38d86a7b9eb81cf9df333e4143cbc6b82e8c3ee13465f9ec663baff85042b','{"name":"Cable Triceps Press","instructions":"A single arm exercise that starts with the hand close to the chest with with the elbows bent, and the elbow flared out. Press forward and down against the cable straightening the elbow.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1661/","author":"Shiladree","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:c867836d-2929-4977-b23c-014bc21ec08d','wger-english-2026-09-08',145,'2026-07-23T12:36:14.006304+02:00','823d79f5a00ff97f449435eaeb25184f4ea0cfe3800c8c7747dfb7066eb8f268','{"name":"Cable Woodchoppers","instructions":"Set cable pulley slightly lower than chest height. Keep body facing forward with hips stable. Grab the pulley handle, fully extend your arms and bring your arms forward and across your body. Hold for 1 second at the end of the movement and slowly return to starting position.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/145/","author":"robhoyt","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:0d79f259-3b28-4258-8a08-cffec062a710','wger-english-2026-09-08',146,'2026-06-19T18:46:26.446370+02:00','1f702ad4a4af8e3b424fdcdeabb9226c0aca45d2160b5d76b5e5c9339df8f9cb','{"name":"Calf Press Using Leg Press Machine","instructions":"Put the balls of your feet on an extended leg press pad. Use your calves to press the weight by flexing your feet/toes into a pointed position, and releasing back into a relaxed position. This exercise builds mass and strength in the Gastrocnemius and Soleus muscles as well, if not better, than any calf exercise.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/146/","author":"nate303303","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:efeccb1b-73c0-4303-8542-bb4f45ef831a','wger-english-2026-09-08',1466,'2026-04-15T22:23:53.094182+02:00','c144e8d78924577ab6ea26ce02ed5e5614ad69e1ad230f86399e2553611c5270','{"name":"Calf Raise using Hack Squat Machine","instructions":"Ideally using a trapeze addon, Lift the weight up using your calves by getting on your toes.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1466/","author":"Expenses7000","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:db4eaf0f-f4d4-4e63-b9fb-258985bc2858','wger-english-2026-09-08',1203,'2026-06-19T18:50:19.274946+02:00','a5592fd623b8f44e0526a183daf3d22f47a9aeb9e86de787d38ffb384951cd88','{"name":"Calf raises, left leg","instructions":"Stand on the floor or on the edge of a step to increase the range of movement. Raise one foot. Lift your heel until you''re standing on your toes. (variable) Stay in this position for three seconds Slowly lower your foot until you almost touch the ground with your heel - don''t slam your foot!","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1203/","author":"wakanda90","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:95a9cc46-270e-45f2-8a17-5665a23ff70b','wger-english-2026-09-08',148,'2026-06-19T18:46:26.971016+02:00','8ec379eb17e90b25ffc838dc5582b56fc782d617775ebb02dc5c28e43496ab16','{"name":"Calf Raises on Hackenschmitt Machine","instructions":"Place yourself on the machine with your back firmly against the backrest, the feet are on the platform for calf raises. Check that the feet are half free and that you can completely stretch the calf muscles down. With straight knees pull up your weight as much as you can. Go with a fluid movement down till the calves are completely stretched. Repeat.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/148/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:b02825ca-bbe4-4a07-a162-2b7a6c0a662b','wger-english-2026-09-08',1911,'2026-06-19T18:56:29.972093+02:00','866e4b66b9be3f11828e33e9e2fc70c8361ac184c1692db847fdadf622f8b5c9','{"name":"Cat Plank","instructions":"On your fours and raise the knees of the floor ever so slightly. Curl your back out and push back from your shoulders as to resemble a cat making itself look large.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1911/","author":"cybro","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:aa22b0b7-795d-47a6-8c0b-fdd0f6b9c8fc','wger-english-2026-09-08',1774,'2026-07-23T12:25:15.989139+02:00','f98a2a08ddf2f0177f0617304283d980f2cb9d777a76539921ec62ed4e8a01a8','{"name":"Chair dips","instructions":"Starting position: Sit down on the front edge of a chair, back straight, hands holding the front edge. Still holding the edge of the chair, arms extended, lift your butt and walk forward slightly so that it is a few inches from the chair. Steps: Slowly lower your body, keeping the back straight, until your arms are at a right angle. Raise your body again to the initial position, arms extended. Repeat.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1774/","author":"tinman","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:5c414175-fe72-455a-ba8f-a0575cf792bd','wger-english-2026-09-08',129,'2026-07-02T16:14:27.445801+02:00','c0a9cb8e9ffe1387187b1d062e1ed5baf31850dd951b8cb17aacb5111978ccc3','{"name":"Chest Press","instructions":"Adjust the seat height so that the grips are parallel to your chest. Use your legs to push the foot forward pedal. Bring the handles to the start position. Keep your back in contact with the back pad, press outwards. Press the handles away from your chest and exhale. Allow the handles to come in gently until they reach your chest. Allow the handles to return to your chest as you inhale.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/129/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:25cbc266-aa84-44f5-989b-53c9cc8fdc77','wger-english-2026-09-08',1825,'2026-06-19T18:55:36.365751+02:00','5e1a63621701d8737efa974b4996dbcc442e9292c968b129243f8fa75a24d3cb','{"name":"Chest-Supported Rear Delt Raise","instructions":"\"The Y\"Position: Set an incline bench to 30-45 degrees. Lie face-down with your chest supported, keeping your head neutral or looking slightly down to avoid neck strain.Grip: Hold light dumbbells with a neutral or thumbs-up grip (thumb pointing to the ceiling).Movement: With straight or slightly bent elbows, raise the dumbbells up and out in a \"Y\" shape. Focus on moving the shoulders and shoulder blades rather than just lifting the arms.Top Position: Squeeze the shoulder blades together and reach high, ensuring the arms are angled to form a \"Y\".Control: Lower the dumbbells slowly to the starting position.","equipment":["Bench","Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1825/","author":"beagle","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:ca3ca5d0-5231-4420-ad06-fa3d32693a1b','wger-english-2026-09-08',1823,'2026-06-19T18:56:00.805800+02:00','acbe8b5968394de6cbddc14a1d070c0675e3a06c0fa57feb153accf0dce11cd1','{"name":"Clamshell","instructions":"Position Side plank with the elbow and the forearm on the ground and the legs slightly bent. Execution Lift your upper knee while keeping your feet close together, like a “shell opening,” then slowly return to the starting position. Keep your core stable and your hips aligned.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1823/","author":"teus_ergaster","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:f77b7cc6-e163-4f92-afa8-5ec431f32588','wger-english-2026-09-08',2449,'2026-06-19T18:48:48.109513+02:00','f26f4d29ebf128b9787428b1d5f90e864c17c659a1a97f87fab6fda723f19110','{"name":"Clamshell to Reverse Clamshell","instructions":"Lie on your side with your hips and knees bent, keeping your legs stacked. Lift your top knee into a clamshell position and keep the leg elevated throughout the movement. From there, alternate between opening the knee upward and lifting the foot upward, moving through hip external and internal rotation. Keep the movement slow and controlled. Do not let the top leg rest on the bottom leg between repetitions.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2449/","author":"TobiasFalk","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:fdeb0973-121f-494d-8b94-54f1d7ba003f','wger-english-2026-09-08',1554,'2026-06-19T18:54:10.864491+02:00','0032279318501f29d5f96916c7f66a538cb9bda7082354d556f8bccdb8ea9fc3','{"name":"Clap Push-UP","instructions":"The clap push-up is an explosive upper body movement that builds power and fast-twitch muscle strength. It adds a plyometric challenge to the traditional push-up by requiring the hands to leave the ground mid-rep. Start in a strong push-up position with your hands slightly wider than shoulder-width and core engaged Lower your body explosively and push off the ground with enough force to lift your hands. Quickly clap your hands together at chest level before returning them to the floor. Land with soft elbows to absorb the impact and immediately move into the next rep","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1554/","author":"Settebello","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:ecf9c0e2-a1d0-4e6e-90e9-5c029e98f2c9','wger-english-2026-09-08',1223,'2026-04-15T22:23:53.152363+02:00','c9a7a6dee2d5a87d8c94f88a2b48b75a3b18914d7b789f4e1d0b25cc6ef56808','{"name":"Claps over the head","instructions":"Stand with your feet shoulder width apart. Raise your arms and clap over your head","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1223/","author":"Lynn_McIntyre","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:a8f76beb-b6d8-430b-8e45-cc03d4959043','wger-english-2026-09-08',1438,'2026-04-15T22:23:53.154276+02:00','a1793761556f3634a82540ae4b34da9307d5095eec2a4007775709702a4a9c89','{"name":"Clean","instructions":"Regular olympic lift clean. Pull bar from ground, catch on shoulders performing a front squat.","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1438/","author":"M9","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:2a125f64-1d10-4926-95ad-33a48e61b3d6','wger-english-2026-09-08',1901,'2026-06-19T18:56:20.460798+02:00','0a625cc26ab7e32594a80969fa2cac32786c32c14b6f0c13d5bfa5ef65d7cb75','{"name":"Clean and Press","instructions":"The First Pull: Lift the bar from the floor to knee-height by driving with the legs, keeping the angle of your back constant. The \"Power\" Position: As the bar reaches mid-thigh, explosively shrug and extend your hips to create vertical momentum. The Quick Elbow Turnover: In the catch phase, rotate your elbows rapidly under the bar to create a \"shelf\" on your front deltoids. The Vertical Press: Press the bar in a straight line; your head should shift slightly forward once the bar clears your forehead to reach full lockout.","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1901/","author":"nishant0712","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:2536b8cd-a287-48ee-b8da-58d8bd595f43','wger-english-2026-09-08',1449,'2026-06-19T18:52:49.280871+02:00','3759419e5c1cd47c88a6234429678ccb9d185c028fe4b76cd18539197981d849','{"name":"ClimbMill","instructions":"The ClimbMill, also known as a stair climber, is a cardio-focused machine that simulates climbing stairs. It provides an effective way to improve endurance while strengthening the lower body. To use the machine, step onto the moving stairs, maintain an upright posture, and use the handrails for balance if needed. Adjust the speed and intensity to match your fitness level. This exercise helps improve cardiovascular health, burns calories, and enhances lower body muscle endurance.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1449/","author":"hpmbala@gmail.com","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:63fbb8e5-6ebc-4def-8844-3e65e097213b','wger-english-2026-09-08',158,'2026-06-19T18:46:24.894703+02:00','c5309d33334685b1567b8a7dc817615afc469cc45ba99c3786a24cdf12fca122','{"name":"Close-grip Lat Pull Down","instructions":"Grip the pull-down bar with your hands closer than shoulder width apart, with your palms facing away from you. Lean back slightly. Pull the bar down towards your chest, keeping your elbows close to your sides as you come down. Pull your shoulders back at the end of the motion.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/158/","author":"tuckerm","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:44cfa56c-d8c2-4f2c-8b5a-f29810fd60e7','wger-english-2026-09-08',1086,'2026-06-19T18:49:23.374725+02:00','b4326da778d5df5b08e9d871a7c4029162346da6e61b38897cb492c79fce29ea','{"name":"Close-grip Press-ups","instructions":"Drop into a strong plank position, bringing your hands close together until they''re almost touching. (picture 1)Bend your elbows to slowly bring your chest to the floor (picture 2). Keep your elbows close to your body as you push back up explosively. Repeat. Ensure you take your time lowering on each rep, keeping your form sharp.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1086/","author":"philip","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:4eb41bfb-cbeb-4683-b9c6-902ee7e028e0','wger-english-2026-09-08',1127,'2026-07-23T12:36:25.919621+02:00','6f015cf3e91acf94315c3600ed8cb6948350be2298ef789e28d5437ad95b6130','{"name":"Close-grip supinated lat pulldown","instructions":"Downward movement • Pull the bar down so that it passes close to your chin and touches the upper part of your chest. • Keep the rest of your body still.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1127/","author":"Franpol","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:d8d1b919-94e1-4e91-b37e-29bb8a479740','wger-english-2026-09-08',1450,'2026-06-19T18:52:49.956450+02:00','a6510eee89307d4a7ede0071cabbf252ea2dd781b4a27d4c89ee5ad08a2ebc9c','{"name":"Cobra Stretch","instructions":"The Cobra Stretch is a back extension exercise that helps improve spinal flexibility and relieve lower back tension. To perform, lie face down on the floor with your hands placed under your shoulders. Press your palms into the floor and lift your chest while keeping your hips on the ground. Keep your elbows slightly bent and your shoulders relaxed. Hold the stretch for a few seconds, then slowly lower yourself back down. This exercise is beneficial for improving posture and reducing lower back stiffness.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1450/","author":"hpmbala@gmail.com","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:e872658a-3bac-4d9e-bcf2-15919ebea43a','wger-english-2026-09-08',980,'2026-07-23T12:08:28.790763+02:00','5acc0b855c3ced7cef22b4bccf9e6166f5357b915de5d9e0c36ef79f068e472a','{"name":"commando pull-ups","instructions":"variation of the pull-up exercise, it is performed with a grip of one hand supine and one hand prone, do not twist the torso to get back to the front, the head passes once to one side, once to the other.","equipment":["Pull-up bar"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/980/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:1544c78d-fe6d-423d-876e-0ba1998063c6','wger-english-2026-09-08',2487,'2026-07-22T07:50:08.630953+02:00','d32460601cc4f100316aa137da5c84d875a54b09f08d9b6ffd3ddf60b1ef881d','{"name":"Cool-Down Swim","instructions":"Swim at an easy, unhurried pace — freestyle, backstroke, or just floating/gliding — with zero focus on technique or drills. The only goal here is to let your heart rate come down gradually and your muscles relax before you get out of the pool.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2487/","author":"Imported from swim plan","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:dbed4613-e1d5-483f-90ae-6db5d593911e','wger-english-2026-09-08',1605,'2026-06-19T18:54:39.328710+02:00','5833707ec3563b5eda56969d497dc77f3183f989f549ad6189099aa735ed1bc9','{"name":"Copenhagen Adduction Exercise","instructions":"Lie on your side with the elbow placed directly under the shoulder, similar to a side plank position. Place the upper leg on a bench with the inside of the foot or ankle resting on it. Lift your hips and hold your body in a straight line while keeping the lower leg off the floor. The exercise strongly activates the adductors of the upper leg while also challenging the core and hip stabilizers.","equipment":["Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1605/","author":"RiccaBaro","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:1b140999-e1fa-49b5-9f2b-690bac959db3','wger-english-2026-09-08',1912,'2026-06-19T18:56:31.365558+02:00','064802809b36e7efa917297dd18c36db7bf7e267201e7b1b380c56f62dd85d12','{"name":"Core Rotation","instructions":"Sit back, raise feet above the ground with knees bent and start rotating left and right with hands touching the ground every move.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1912/","author":"cybro","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:96a899ee-16a4-457d-8f66-efdd39fd38a0','wger-english-2026-09-08',1407,'2026-06-19T18:52:27.401602+02:00','e79511c6700f17e5839850307444b057faaf6037fadc0acd027ca362d3ad711a','{"name":"Cossack squat","instructions":"The Cossack Squat is a multi-joint exercise that works mainly on the legs and buttocks, but also involves stabilizing muscles. It is an excellent exercise for improving strength, mobility and stability in a functional way.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1407/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:26168c76-5e2a-4321-8755-5ca42bd341ad','wger-english-2026-09-08',2525,'2026-08-16T23:58:32.243684+02:00','5fffda0b5b59139a2403bd4f4e37efa73cbfce26435413479a8408091f025632','{"name":"Couch Stretch","instructions":"Stand facing away from a bench, couch or similar-height object. Extend one leg backwards, resting your foot \"laces-down\" on the edge of the bench. Lower yourself until your rear knee is on the floor and you are in a lunge position, with your torso hanging forwards slightly. Brace your core, tense your rear glute, and straighten up your torso to vertical, under control. Relax and repeat. Repeat for the other leg, too.","equipment":["Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2525/","author":"Croak6728","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:6e00afb6-272d-44a2-8ae3-e7fa41b50f06','wger-english-2026-09-08',161,'2026-06-19T18:42:57.213301+02:00','d707c2323274c184e70aa7f75c2b8659986c590cc261b6a885ca3b521def376c','{"name":"Cross-Bench Dumbbell Pullovers","instructions":"Grasp a moderately weighted dumbbell so your palms are flat against the underside of the top plates and your thumbs are around the bar. Lie on your back across a flat bench so only your upper back and shoulders are in contact with the bench. Your feet should be set about shoulder-width apart and your head should hang slightly downward. With the dumbbell supported at arm''s length directly about your chest, bend your arms about 15 degrees and keep them bent throughout the movement. Slowly lower the dumbbell backward and downward in a semicircle arc to as low a position as is comfortably possible. Raise it slowly back along the same arc to the starting point, and repeat for the required number of repetitions.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/161/","author":"powerade69","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:37314b67-1aad-4405-aa88-70846d5f035d','wger-english-2026-09-08',1458,'2026-07-23T12:36:31.245830+02:00','ed95e6d27b12b4e936b39f4667331a7d55a8ba090cfcc9b0b1052057d568b5cd','{"name":"Cross-Body Cable Y-Raise","instructions":"Attach a D-Bar to the cable machine. Perform a motion akin to drawing a sword from across your body.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1458/","author":"Expenses7000","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:4f38cc2e-5904-4ef5-b811-e729105cfd3b','wger-english-2026-09-08',1400,'2026-06-19T18:52:24.696633+02:00','7ad77b08d1a7901b5765c50741aaaab953703b17a9f6097bfd199414f2cdcbe4','{"name":"Crossbody Hamstring Stretch","instructions":"While standing, cross one leg behind the other (keep this leg straight). Reach downward and try to touch the toes of that leg. Slightly bend the other leg so that you can bend down.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1400/","author":"captive0592","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:bb948d34-8948-4995-9e59-003d7b6fc1b2','wger-english-2026-09-08',1395,'2026-06-19T18:52:19.320998+02:00','c145d5c46e98a15d1c77817247c256c38cfe85554059ef75ec25ea0b96884053','{"name":"Crossbody Leg Swings","instructions":"Hold onto a wall or something near you for support. Swing one leg across the front of your body, then back and out to the side. Repeat while slowly increasing your range of motion.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1395/","author":"captive0592","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b186f1f8-4957-44dc-bf30-d0b00064ce6f','wger-english-2026-09-08',167,'2026-04-15T22:23:56.689712+02:00','f755c7a27bde148a439581b44728784446b584ac57b89fff072b9865f1c84c7e','{"name":"Crunches","instructions":"Lay down on your back a soft surface, the feet are on the floor. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back.","equipment":["Gym mat"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/167/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:401989e0-64c3-459d-bc47-2c171ab4f41d','wger-english-2026-09-08',172,'2026-06-19T18:46:28.487838+02:00','9ba828f201fbb2e2da080dda8372843b26055f57852c9d5ad2098c9ca68b2246','{"name":"Crunches on Machine","instructions":"The procedure is very similar as for regular crunches, only with the additional weight of the machine. Sit on the machine, put both feet firmly on the ground. Grab the to the weights, cables, etc. and do a rolling motion forwards (the spine should ideally lose touch vertebra by vertebra). Slowly return to the starting position.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/172/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:29175281-afaf-4ffd-85e8-cfc38493e304','wger-english-2026-09-08',173,'2026-07-23T12:36:14.430709+02:00','2d6fe15860038734b638f6224b694c48fe390d1b6e8bbed88b74bfa6b8cf2b0e','{"name":"Crunches With Cable","instructions":"Take the cable on your hands and hold it next to your temples. Knee down and hold your upper body straight and bend forward. Go down with a fast movement, rolling your back in (your ellbows point to your knees). Once down, go slowly back to the initial position.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/173/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:b7ff64bc-7a7c-4dbc-af6f-fabc20425f5f','wger-english-2026-09-08',174,'2026-06-19T18:56:52.199628+02:00','2e20d75fe7e2e6b2f99d967e7852ec52eafa5a77e82362176ad8bcb5835a1a50','{"name":"Crunches With Legs Up","instructions":"On your back, legs extended straight up, reach toward your toes with your hands and lift your shoulder blades off the ground and back.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/174/","author":"krisbbb","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:4b67ccf1-6bbc-406a-b88b-e2f72b10085e','wger-english-2026-09-08',2452,'2026-06-21T10:44:58.832138+02:00','3f36068c21917319ba3051651df5a1764f17abceeea7e2eb819c3d91e997a9e8','{"name":"Curl De Muñeca Con Barra","instructions":"This is a variation of the flat bench press designed to emphasize the clavicular head of the pectoralis major (the upper portion). By tilting the torso, the angle of the push changes, shifting more tension to the upper chest and shoulders, which helps achieve a more aesthetic, balanced, and three-dimensional development of the torso. Starting Position: Grip a bar with an overhand grip (palms facing up) at a width similar to your shoulders. Position on the Bench: Kneel in front of a flat bench and rest the backs of your forearms on it. Your wrists and hands should extend slightly beyond the edge of the bench to allow for a full range of motion. Eccentric Phase (Lowering): Lower the bar in a controlled manner by extending your wrists toward the floor. At the bottom of the movement, slightly spread your fingers to let the bar roll down a bit, maximizing the stretch. Concentric Phase (Lift): First, close your fingers to secure the bar, then flex your wrists upward explosively but in a controlled manner, bringing the bar as high as possible. Strongly contract your forearms at the top position for one second. Form: Keep your forearms firmly pressed against the bench throughout the exercise; only your wrists and fingers should move.","equipment":["Barbell","Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2452/","author":"xWan","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:9828f705-350b-4afd-86c4-fcc0e8a0fb4b','wger-english-2026-09-08',1666,'2026-06-19T18:51:38.411754+02:00','9c6790dc1c328f69d53caa405dc2fca48f1dc05fd2f2f2b7be1f624cf7225e89','{"name":"Curl - With Shoulder Elevated","instructions":"Place elbow so that it is about level with the shoulder. Curl the wieght to your shoulder. Focus on the stretch in the eccentric part of the curl","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1666/","author":"Shiladree","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:804cd574-1247-4035-915b-47ceab94e78e','wger-english-2026-09-08',2534,'2026-08-27T17:57:05.638323+02:00','89c0da15de02f79110b5f30185679bef34ec17a01a0ff59d3d108a95eecbc8e5','{"name":"(D) Puente de glúteos","instructions":"Lie on you back with your hips and knees flexed, feet on the ground. From this position, raise your butt off of the ground to a height where your body makes a straight line from your knees to your shoulders. To make the exercise more intense, you can add weight by letting a barbell rest on your hips as you complete the motion, or you can put your feet on a slightly higher surface such as a step or a bench.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2534/","author":"dvdfernandez95","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:2dd388dd-e7fa-44f1-9973-6f9c1185e0a4','wger-english-2026-09-08',2497,'2026-08-10T03:35:16.265364+02:00','1588d0b99caf99ffcfccc5122fd40e780e06871287581449e1373821d1e12bb8','{"name":"DB Floor Press (5kg Single Arm)","instructions":"Vasco custom single-arm DB floor press for 5kg dumbbell home training. Unilateral work for symmetry and core anti-rotation. Part of Monday Push day.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2497/","author":"Vasco Custom","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:6e5e15f0-5722-46d6-ad89-719c581da436','wger-english-2026-09-08',2504,'2026-08-10T03:39:53.104928+02:00','ae61a24dfa07cf700c20f6bc9c3931ed64b1b396017f8fdda0f92aa9fd067886','{"name":"DB Hammer Curls (5kg)","instructions":"Vasco custom single-arm hammer curl for 5kg dumbbell. Targets brachialis for arm thickness. Part of Tuesday Pull day.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2504/","author":"Vasco Custom","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:ef7d621e-ddb2-490f-ae2b-e73dd509d396','wger-english-2026-09-08',2502,'2026-08-10T03:38:32.695918+02:00','27aabaeb9ce3b9a839e070b8dbed1c88f24d7e72312a7253d7d05ef1fff250b8','{"name":"DB Single-Arm Row (5kg)","instructions":"Vasco custom single-arm DB row for 5kg dumbbell home training. Unilateral horizontal pull. Part of Tuesday Pull day.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2502/","author":"Vasco Custom","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:7b40813b-80a3-42cc-8938-0c5199ef7620','wger-english-2026-09-08',1497,'2026-04-15T22:23:53.371750+02:00','8c02ce94aeaa97fb34e141e241ae9627a7e1603ba21bf46bb32641adf4b88ee3','{"name":"DB Underhand bench press","instructions":"Underhand grip DB, perform a normal bench press movement, keeping the elbows close to the chest","equipment":["Bench","Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1497/","author":"JohnPreston","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:4b23738a-67a8-41af-996d-abc53a7c3f97','wger-english-2026-09-08',1496,'2026-06-19T18:53:24.565662+02:00','a3164323f19f41ecbf2e02e4c49d05c8c0bfbd4691d4b24253ed62b42887a58f','{"name":"DB Upper Chest Variation","instructions":"Dumbbell in hand in a curl fashion, lean body into the arm to help the dumbbell up above the chest, next to the head, to activate chest and delt combo","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1496/","author":"JohnPreston","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:73646b21-62e3-493b-8d75-4179326cd404','wger-english-2026-09-08',1881,'2026-06-19T18:55:55.325197+02:00','86a685bc01bde449f94b7f16c44d62d07a837ef6ea552d2269ed904b2defb2f2','{"name":"DB Wrist Extension","instructions":": Grab two dumbbells with an overhand grip and lay your forearms across your knees. : Let your wrists flex fully, then extend your wrists.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1881/","author":"Deflation","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:816d8bff-73c0-436c-8479-e0145f2324fc','wger-english-2026-09-08',2505,'2026-08-10T07:15:35.268051+02:00','8e2023a866748259bb612909e0cd7da2aaca9866c98413f265e4d9c3a5b92004','{"name":"Dead Bug (Core L1)","instructions":"Vasco custom dead bug - foundational deep core stability and anti-extension. Teaches lumbar-pelvic dissociation, breath-coordination, and proximal stability for distal mobility. Prerequisite for all core training.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2505/","author":"Vasco Custom","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:d4db2355-4c99-4d80-a179-6aeced7c7fed','wger-english-2026-09-08',178,'2026-07-23T12:24:55.948093+02:00','90397b7ff82baa87baa1c04826046095071b558c66d3c03d7c05f420cbe6941b','{"name":"Deadbug","instructions":"Lie on your back, with your hips and knees bent to 90°. Raise both arms toward the ceiling. Pull your lower back to the floor to eliminate the gap. Start by pressing one leg out, and tapping the heel to the floor. \"As you extend one leg, exhale as much as you can, keeping your lower back glued to the floor,\" Dunham says. When you can’t exhale any more, pull your knee back to the starting position. Make this more difficult by holding weight in your hands, or by lowering opposite arm and leg.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/178/","author":"Metin","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:74d4697d-8a97-4ea2-9d05-fa4d2bd7221e','wger-english-2026-09-08',182,'2026-04-15T22:23:56.023466+02:00','452c768ccc96dc0ffc8e6a79876dfd391e95a54b165d05498f4a5df807174a46','{"name":"Deadhang","instructions":"Deadhang performed on an edge either with or without added weight (adujst edge or weight to adjust difficulty)","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/182/","author":"2dPREtEZP221u68Akf0JImv5L48","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:ee8e8db4-2d82-49e1-ab7f-891e9a354934','wger-english-2026-09-08',184,'2026-06-19T19:55:07.473226+02:00','961ea2e8fdb0adfaecc6e47182632c682c6abda0149cfe0e2698c23d18ccebc1','{"name":"Deadlifts","instructions":"Stand firmly, with your feet slightly more than shoulder wide apart. Stand directly behind the bar where it should barely touch your shin, your feet pointing a bit out. Bend down with a straight back, the knees also pointing somewhat out. Grab the bar with a shoulder wide grip, one overhand, one underhand (mixed grip). Pull the weight up. At the highest point make a slight hollow back and pull the bar back. Hold 1 or 2 seconds that position. Go down, making sure the back is not bent. Once down you can either go back again as soon as the weights touch the floor, or make a pause, depending on the weight.","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/184/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:9ac4813e-79a6-4a4d-ab93-9cfa5bf7b8fa','wger-english-2026-09-08',1889,'2026-06-19T18:56:47.273727+02:00','95d2f13ddeb1c583ef8aae6a40bf533c418dcda360caaf3600c19d6fcb641c5f','{"name":"Decline Bench Leg Raise","instructions":"Setup : Lie on a decline bench with your head at the top and grip the handles. The Start : Extend legs fully, keeping them slightly elevated to engage your core. The Lift : Raise your legs toward the ceiling using your abs, not momentum. The Squeeze : Pause and contract your lower abdominals at the top. The Return : Lower your legs slowly to the starting position with control.","equipment":["Incline bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1889/","author":"nishant0712","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:bcd801f0-9a38-4615-a91c-900153c8c234','wger-english-2026-09-08',185,'2026-07-23T12:08:35.224422+02:00','fab2561e74ab40a0d350accd500471dc766ca0d8e382872519e3042401622694','{"name":"Decline Bench Press Barbell","instructions":"Lay down on a decline bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up.","equipment":["Barbell","Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/185/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:dda69c96-62d4-4690-aa07-a4a0f6ceb63a','wger-english-2026-09-08',186,'2026-07-23T12:08:35.631556+02:00','1121590dfe6e5694f343c57eb4cf38307b735970ff4b573471d30803b99fd1fe','{"name":"Decline Bench Press Dumbbell","instructions":"Take two dumbbells and sit on a decline bench, the feet are firmly on the floor, the head is resting the bench. Hold the weights next to the chest, at the height of your nipples and press them up till the arms are stretched. Let the weight slowly and controlled down.","equipment":["Bench","Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/186/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:fae44c34-2e85-4d22-8fb8-7b14faf14719','wger-english-2026-09-08',1591,'2026-06-19T17:30:03.297348+02:00','fa0de5d76332b26750781d650a86274d292d09f85baa0d99a891c10f50fe083e','{"name":"Deep breathing (standing or seated)","instructions":"A conscious breathing technique to improve oxygenation, reduce stress and connect with the present moment.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1591/","author":"MrAlfaRobot","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:e7a964cd-e68e-4926-bc7c-577065137e18','wger-english-2026-09-08',189,'2026-06-19T18:46:30.033946+02:00','6d2fe1a70d136f2e0d7912196eea7a80447a8d1f20ff8d1b1ccfa47571929ac6','{"name":"Deficit Deadlift","instructions":"Preparation Stand on weight plate, bumper plate, or shallow elevated platform with loaded bar above feet. Squat down and grasp bar with shoulder width or slightly wider overhand or mixed grip. Execution Lift bar by extending hips and knees to full extension. Pull shoulders back at top of lift if rounded. Return weights to floor by bending hips back while allowing knees to bend forward, keeping back straight and knees pointed same direction as feet. Repeat. Comments Throughout lift, keep hips low, shoulders high, arms and back straight. Knees should point same direction as feet throughout movement. Keep bar close to body to improve mechanical leverage. Grip strength and strength endurance often limit ability to perform multiple reps at heavy resistances. Gym chalk, wrist straps, grip work, and mixed grip can be used to enhance grip. Mixed grip indicates one hand holding with overhand grip and other hand holding with underhand grip. Lever barbell jack can be used to lift barbell from floor for easier loading and unloading of weight plates. Barbell Deficit Deadlift emphasizes building strength through lowest portion of Deadlift. Target muscle is exercised isometrically. Heavy barbell deadlifts significantly engages Latissmus Dorsi. See Barbell Deficit Deadlift under Gluteus Maximus. Also see Deadlift Analysis.","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/189/","author":"bobbyprince89","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:bb9b994e-426f-4693-9d16-3f8d5a9c72b8','wger-english-2026-09-08',1556,'2026-06-19T18:54:13.590536+02:00','d665550d75ca7b27f798c328438b7f6029b492f15f0dbacdbe98abc18b45b0f5','{"name":"Devil’s Press","instructions":"The Devil’s Press is a hybrid movement combining a dumbbell burpee and a double dumbbell snatch. It’s a full-body, high-intensity exercise that develops strength, power, and metabolic conditioning. Start with a dumbbell in each hand and perform a burpee, letting your chest touch the ground while holding the dumbbells. Explosively jump your feet forward and swing the dumbbells between your legs. Drive the dumbbells overhead in one continuous motion, locking out your arms. Lower the dumbbells with control to return to the starting position and repeat","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1556/","author":"Settebello","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:14d5cdbc-9b17-4296-a282-0a81cd3c4c4e','wger-english-2026-09-08',193,'2026-06-19T20:01:08.565413+02:00','d28ca779e7b08e9dac7f001b286ebb8471c2cc053eaabf14d5ab24577b8bf34f','{"name":"Diagonal Shoulder Press","instructions":"You sit at the bench press device, back slightly tilted to the back. The bar should be about 20 cm in front of you. Then you push the bar and take it back again, as you would with a bench press. In this position you strain your chest muscles a lot less, which is nice if you want to train, but your chest hasn''t recovered yet.","equipment":["Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/193/","author":"oboema","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:de22963a-5d42-4999-860e-377f64359432','wger-english-2026-09-08',386,'2026-06-19T18:57:05.511643+02:00','b11fe121b5636009bf4775b7984776f684826c60fc86c01392fe05b00921765f','{"name":"Diamond push ups","instructions":"Start: Get into a plank. Place hands close together under your chest so thumbs and index fingers form a diamond shape. Lower: Bend your elbows to lower your chest toward your hands. Keep your body straight. Push: Push back up until arms are fully extended. New note Keep elbows close to your body and core tight.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/386/","author":"notdefine","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:7c8eb1ac-2d7e-4ca7-919a-1848ba38e0f4','wger-english-2026-09-08',197,'2026-06-19T18:46:37.190865+02:00','e04217441ec9404ae0032d71c7587d385f5479d15d6d9ab3de9ea91af9a1d5a3','{"name":"Dips Between Two Benches","instructions":"Put two benches so far appart, that you can hold onto one with your hands and are just able to reach the other with your feet. The legs stay during the exercise completely stretched. With your elbows facing back, bend them as much as you can. Push yourself up, but don''t stretch out the arms.","equipment":["Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/197/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:adbb1d4c-962b-4a26-a353-9c47a2b37a93','wger-english-2026-09-08',1713,'2026-06-19T18:49:07.728655+02:00','2ea2489884ca82af15bed48ee97d5a029e66dbc84c8aa6123d4fdb91ddc98e97','{"name":"Doorway Pectoral Stretch","instructions":"Place the forearm vertically on a door frame or stationary object at head height Step forward past the arm, keeping it still against the object to stretch the chest","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1713/","author":"Croak6728","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:fe249e2f-5856-420f-8a34-1b02c7fde141','wger-english-2026-09-08',1360,'2026-06-19T18:51:57.962481+02:00','6f9e5d90d0770fbc18e7008e1b5538543a49900b71d53a98c3a71104cec19fd8','{"name":"Double Kettlebell Clean and Press","instructions":"Full-body muscles building exercise. This exercise provides a huge range of benefits in terms of strength & size and is extremely functional.","equipment":["Kettlebell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1360/","author":"m4k3r","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:a030a4e9-970c-4442-b0b3-e49b42143de0','wger-english-2026-09-08',1361,'2026-04-15T22:23:53.461982+02:00','223db313623a981701ed8b52469acb4a1afeba50b468237c1e4d3511eed839b8','{"name":"Double Kettlebell Front Squat","instructions":"The kettlebell front squat is a compound, multi-joint exercise that works several muscle groups.","equipment":["Kettlebell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1361/","author":"m4k3r","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:f0823bb5-3f18-48d4-98de-cbe38f9fd8ff','wger-english-2026-09-08',1827,'2026-07-23T12:08:34.023239+02:00','457a3cb7408a8e0bd4ae5021bfd20f452d188b565927f0ae2839e7ec565533d8','{"name":"Double-Leg Abdominal Press","instructions":"Lie on your back with knees and hips bent at 90 degrees (tabletop). Place your hands on your thighs just above your knees. Push your hands against your knees as hard as possible while using your abs to pull your knees toward your hands. Hold for 10 seconds of maximum effort. Your abs should be shaking.","equipment":["Gym mat"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1827/","author":"beagle","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:58ca3e51-ea64-4771-a74a-a74d29f5c40c','wger-english-2026-09-08',1243,'2026-06-19T18:50:59.048473+02:00','67cc6a155e42b4cacdeffa388b446fc127c4077d53de662ec97e9401bc06c4f8','{"name":"Double Leg Calf Raise","instructions":"The double leg heel raise is important to strengthen and create control and stability around the ankle and knee, and provide balance and control for the hip and pelvis.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1243/","author":"erikocobra","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:02b96dc1-d1d9-4fc7-b54c-82dda1691485','wger-english-2026-09-08',1481,'2026-07-23T12:36:33.297091+02:00','67def7c34ac57e70d3fd7164c390b0e2c9078248fc6cebbe24a69ef589772bed','{"name":"Drag Pushdown","instructions":"Starting position for this rope pushdown is standing facing a cable machine with the handles of a rope attachment in both hands and feet shoulder width apart. Hinge forward slightly at the hips maintaining an upright chest and bring the shoulders and elbows behind the body so that when you push down on the cable attachments, you can get a fully contracted triceps long head. Drag the cable machine rope attachment as close to the body as possible and straighten your elbows until lockout.","equipment":["Cable machine","SZ-Bar"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1481/","author":"Moffi","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:f5ad82a8-adf8-4795-9874-1f6d183c56ed','wger-english-2026-09-08',1409,'2026-06-19T18:52:29.420909+02:00','b6fe7fc35207b85e61c5de9d04574b3e22871713bc62b8f4daa124f364f64cee','{"name":"Dragon-flag","instructions":"Keep your body completely rigid throughout the movement, avoiding sagging in your lower back. Use a firm grip to stabilize your upper body. Start with simpler versions (such as with bent knees) to build strength and control.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1409/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:8c132ea0-7885-474f-8514-0909ae22bdf6','wger-english-2026-09-08',1201,'2026-06-19T18:50:16.604333+02:00','341136c37a1d0d3ba58d6c91809e0fa7afbb6f53010986fb0b4b82fdd4122a40','{"name":"Dragon squat","instructions":"Start standing with your feet hip-width apart. Cross your right foot behind you to the left corner and back of the room while bending both knees. Return and repeat, alternating sides. Keep your hips and shoulders forward as you cross your feet and bend your knees.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1201/","author":"cynomops","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:15ee508d-fbd7-4acf-ab44-e35525582693','wger-english-2026-09-08',1512,'2026-06-19T18:53:34.469881+02:00','1b2c0e534cb1035786e45a14e95766b7e2b985209de78eec1f56b3ac6d66002b','{"name":"Drop Curl","instructions":"Drop curls in a modified position at a slow pace effectively engage the brachialis for arm width. Starting position is with both arms in a slight angle towards each other at chest height with a dumbbell in each hand. Lower one dumbbell close to full extended arm position slowly and in a controlled manner during the first half of the curl, then curl it back up to starting position, while the other dumbbell stays at its starting position. Now lower the other dumbbell down. This keeps tension on the brachialis. As we pass the 90deg mark on our way down, the biceps will take over the work.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1512/","author":"Moffi","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:51ab6376-eb3e-42dc-ad48-46166c94adac','wger-english-2026-09-08',1639,'2026-06-19T18:49:05.019537+02:00','e1dc5230071dea61955b5e8022251ee6dc73a082c16352509f87615dec42bcc6','{"name":"Dumbbell Bent Over Face Pull","instructions":"This exercise involves using dumbbells to perform a bent over face pull, which targets the upper back and shoulders. The movement involves pulling the weights towards the face while keeping the elbows high and squeezing the shoulder blades together.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1639/","author":"AlucardEvil40","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:8675ea3b-0e8b-4a08-9e82-4525ec91dd23','wger-english-2026-09-08',1226,'2026-06-19T18:50:37.645804+02:00','ca8fdc2a01e1875caefb1aa55ecf9d3ecf1704a4ee018afe1b91f98079859feb','{"name":"Dumbbell bicep curl to press","instructions":"Bend your elbows and lift the dumbbells to your shoulders. Push the dumbbells over your head while rotating your arms to make your palms face forward. Reverse it to lower down. Repeat the exercise.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1226/","author":"Lynn_McIntyre","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:82f19d1c-f12b-49f0-bfdd-24239f93eabc','wger-english-2026-09-08',1504,'2026-06-19T18:53:27.638261+02:00','d5870fcb9a9d3cec7f62c77b3a3586c2cb568c02c2797aa3c68581ef6869a92e','{"name":"Dumbbell Bradford press","instructions":"From a front hold of the DBs in a OHP, press above the head, bring back towards the rear of the shoulders, down, and press back forward.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1504/","author":"JohnPreston","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:31a58615-d3ae-4233-9c50-9143c899ce8c','wger-english-2026-09-08',1482,'2026-06-19T18:53:11.890025+02:00','af53c2c971b34123b8bb110a549854ba48d683603859adb79a51a48069622442','{"name":"Dumbbell Cheat Curl","instructions":"Starting position is standing with feet shoulder width apart. Hands should take an underhand or supinated grip on the dumbbells holding them with hands shoulder width apart. Keeping elbows tucked into your sides throughout the entire movement, use momentum to curl the dumbbells, squeezing your biceps at the top of the movement. Slowly lower to return to the starting position. Keep the core tight throughout the exercise. Cheating through the concentric curling portion of this challenging exercise gives us a great opportunity to increase time under tension and create eccentric overload with heavier weight when we lower.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1482/","author":"Moffi","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:428112f3-3918-45ba-870a-dc58cf3959cf','wger-english-2026-09-08',1228,'2026-06-19T18:50:40.701113+02:00','68251f6cb1a70bf8505f4e264d3bc1726df2726c028e36e8a3b8a7c4c35a3f67','{"name":"Dumbbell close grip bench press","instructions":"Lie down with your back on a flat bench. Hold a dumbbell in each hand. Raise your arms towards the ceiling with your palms facing each other and dumbbells pressed together. Slowly lower the dumbbells to your chest, then slowly push them back. Repeat the exercise.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1228/","author":"Lynn_McIntyre","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:46e0f60c-fdc0-489a-82e4-a5b7476a5c21','wger-english-2026-09-08',202,'2026-06-19T18:57:39.114487+02:00','7d0c7130aa5869b970761569de73cd30295f469ecba2fc19c0a16c858af674ee','{"name":"Dumbbell Concentration Curl","instructions":"Sit on bench. Grasp dumbbell between feet. Place back of upper arm to inner thigh. Lean into leg to raise elbow slightly.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/202/","author":"http://www.exrx.net/WeightExercises/Brachialis/DBC","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:b48e4d9d-f7fc-4619-85fb-6dabe5d7c999','wger-english-2026-09-08',1415,'2026-06-19T18:52:32.415387+02:00','6ba49f0e2b3679d9d7be1d1e3959285d0cfbdb6d1f293abd9c5adf00e02256f4','{"name":"Dumbbell Crunches","instructions":"Dumbbell crunches are a weighted variation of traditional crunches designed to target the abdominal muscles more intensely. Lie flat on your back with your knees bent and feet flat on the floor. Hold a dumbbell with both hands close to your chest or above your head. Lift your shoulders and upper back off the ground in a crunching motion, engaging your core. Slowly lower yourself back to the starting position. Ensure controlled movements throughout the exercise to prevent strain.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1415/","author":"hpmbala@gmail.com","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:99846da5-5dc8-4de1-ba55-ae2b4c03c30d','wger-english-2026-09-08',1931,'2026-06-19T18:56:41.784168+02:00','f8c10b01f22c9b25958c0d6dcc3087848958acaa3304e1f60a8ecadf475f6d4c','{"name":"Dumbbell Curl","instructions":"The Dumbbell Curl is a classic isolation exercise for the arms. Unlike the Hammer Curl, it involves rotating your wrists (supination) as you lift the weights, which allows for a full contraction of the biceps.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1931/","author":"amaesc","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:2539f907-0c10-4af5-807c-48cd15fd0878','wger-english-2026-09-08',1616,'2026-06-19T18:54:49.990841+02:00','8e5337fc440b2ba59eafeebb4034ca70ae38709ff9d44dce38d788e371aab60d','{"name":"Dumbbell donkey kick","instructions":"The dumbbell donkey kick is an effective exercise for working the glute and hamstring muscles. This exercise is usually performed on all fours, using a dumbbell to add resistance. The steps for performing it correctly are described below. Starting position: Get on all fours on a mat, with your hands aligned under your shoulders and your knees aligned under your hips. Placing the dumbbell: Take a dumbbell and place it behind the knee of the leg you are going to lift. Make sure it is held securely to prevent it from falling during the exercise. Exercise: Inhale and, as you exhale, lift the leg with the dumbbell upward, keeping the knee bent at a 90-degree angle. Raise the leg until it is parallel to the floor, feeling the contraction in the glutes. Hold the position for one second at the top and then slowly lower the leg back to the starting position. Repetitions: Perform 10 to 15 repetitions per leg, making sure to maintain good form throughout the exercise. Sets: Complete 2 to 3 sets, depending on your fitness level.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1616/","author":"Tierrasverdes","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:2418b290-801c-45fd-a990-fc9f234ab1e5','wger-english-2026-09-08',1224,'2026-06-19T18:50:32.881415+02:00','9a4cb1f83a635da474ec3d4f89791148e3f6ceb4e81d17214fea27871ed0088a','{"name":"Dumbbell drag curls","instructions":"Hold a dumbbell in each hand with your palms facing forward. Pull your elbows back and lift the dumbbells to your chest height. Slowly lower the dumbbell and repeat the exercise.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1224/","author":"Lynn_McIntyre","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:e4966cb8-9089-4595-9c78-99a27821e6ff','wger-english-2026-09-08',1084,'2026-06-19T18:57:47.486181+02:00','d41fa7382b990a8ded0a7865f3ac79826f67cdbf105d5ab9a3e4b8f3f95bfe41','{"name":"Dumbbell Floor Press","instructions":"Grab your dumbbells and lay flat on your back with your knees bent and your feet flat on the ground (use a bench if you have one). Press the weights up, locking out your elbows (A). Lower them slowly until your upper arms are resting on the floor (B) close to your body. Pause here before explosively pressing back up. Squeeze your chest hard and repeat.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1084/","author":"admin","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b407768d-d519-47b8-818a-44c9761a8be6','wger-english-2026-09-08',1503,'2026-04-15T22:23:53.505895+02:00','b6ec84c11ac5b3638bcd2965209c4c10eaf5bc42960454805861733127fd14fc','{"name":"Dumbbell Frog Press","instructions":"Similar to hip thrust, but with feet put up together, lifting the butt off the ground in a frog like position.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1503/","author":"JohnPreston","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:4621b41f-0d32-4033-acff-dc079c792606','wger-english-2026-09-08',1640,'2026-06-19T18:49:28.824471+02:00','d5830e6594cc6d0997679c73843d70e393cd0148ddcad64c7362ec76fe98b8ff','{"name":"Dumbbell Front Squat","instructions":"This exercise involves holding a dumbbell in each hand at shoulder height and performing a squat. It targets the lower body muscles, including the quads, hamstrings, and glutes, while also engaging the core and upper body.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1640/","author":"AlucardEvil40","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b7c6a444-90ea-4f5b-9fea-748311606eaa','wger-english-2026-09-08',203,'2026-06-19T18:56:54.257029+02:00','baec7154b41c5324cec3399f64325759228b0f55279d2f28ecee9c553332d7a0','{"name":"Dumbbell Goblet Squat","instructions":"Grasp dumbbell with both hands at the sides of the upper plates. Hold dumbbell in front of chest, close to torso. Place feet about shoulderwide apart, keep knees slightly bent. Squat down until thighs are parallel to floor. Keep back straight, bend and move hips backward to keep knees above feet. Return, keep knees slightly flexed. Repeat. Keep bodyweight on heels and look ahead or slightly above to keep back straight.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/203/","author":"ataraxie67","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:f0f53b8e-0136-4195-baf3-781903651359','wger-english-2026-09-08',1087,'2026-07-23T12:25:08.253641+02:00','5a0e513bac6b2372449c16eb8b6b7902ba152920dc90a680f6fdd2b8d7d246d0','{"name":"Dumbbell Hang Power Cleans","instructions":"On your feet, stand tall with your dumbbells, holding them at your sides. Hinge at the hips to lower them to your knees (picture 1). Stand back up with a slight jump, using the momentum to pull the dumbbells up on to your shoulders (picture 2). Stand up straight, then lower under control to your sides and repeat. Keep this fast and explosive; if your heart rate doesn’t hit the roof, you’re doing them wrong.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1087/","author":"philip","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:587af8f1-516b-44c3-8660-70f262e1bef8','wger-english-2026-09-08',1353,'2026-07-23T12:25:12.368050+02:00','0045e456b8a404e03d27d43eeed7adb9a68a0328125e16b6b871cedee3d659cd','{"name":"Dumbbell Hex Press","instructions":"Engage the muscles Position your feet wide Controlled movement Slow movement Bring the weights toward your lower chest/stomach","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1353/","author":"Anastasious","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:af77220c-098c-47c2-9f8c-92a651998903','wger-english-2026-09-08',1642,'2026-06-19T18:49:31.505813+02:00','6da6effe26ce353146b6e37f85e1280707d044293aa5223c9cdc42c26270c0ed','{"name":"Dumbbell Hip Thrust","instructions":"This exercise involves sitting on the ground with a dumbbell resting on the hips, then thrusting the hips upward while squeezing the glutes. It is a great exercise for strengthening the glutes and improving hip mobility.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1642/","author":"AlucardEvil40","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:43e85cb8-51d0-4892-b1bf-80a3cb111ff6','wger-english-2026-09-08',204,'2026-06-19T18:46:35.686758+02:00','aa0f33b05caad9e98efce8882c4262986e80d0f3faf98ce74351111ed46dca74','{"name":"Dumbbell Incline Curl","instructions":"Setup: Set an adjustable bench to an incline of approximately 45 to 60 degrees . Starting Position: Sit back against the bench with a dumbbell in each hand. Let your arms hang straight down toward the floor with your palms facing forward (supinated grip). The Curl: Keeping your upper arms stationary and shoulders pinned back against the bench, exhale and curl the weights upward toward your shoulders. Peak Contraction: Squeeze your biceps hard at the top of the movement, ensuring your elbows do not swing forward. The Descent: Inhale and slowly lower the dumbbells back to the starting position, maintaining full control and feeling the stretch in the biceps.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/204/","author":"ExRx","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:dcc6e237-a8bb-4eca-bbc5-7fb852636f6a','wger-english-2026-09-08',206,'2026-07-02T16:14:28.985601+02:00','be4a1aeaf18c6c2218658f766ed7cd0cf5d9576cbfc078abe0e8c3f163144ea5','{"name":"Dumbbell Lunges Walking","instructions":"Starting Position: Stand with feet hip-width apart and hands either on your hips or holding dumbbells at your sides. The Stride: Take a wide step forward with your right leg. The Descent: Lower your hips until both knees are bent at approximately 90-degree angles . The Transition: Drive through your front heel to stand up, bringing your back foot forward to step directly into the next lunge.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/206/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:adb6067f-fd48-4a25-a9b4-0793c5f158fa','wger-english-2026-09-08',1227,'2026-06-19T18:50:38.992200+02:00','66883a5010b6b59bae8979265a7eb477418191e5586228eb01da73499be5c9d1','{"name":"Dumbbell rear delt row","instructions":"Hold a dumbbell in each hand. Bend at your hips to make your back almost parallel to the floor. Let your arms hang down. Keep your arms in line with your shoulders. bend and lift your elbows out to the sides until your upper arms are parallel to the floor. Slowly return and repeat","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1227/","author":"Lynn_McIntyre","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:75e34967-b0ec-40d5-811e-b474b234a7a9','wger-english-2026-09-08',1651,'2026-06-19T18:49:37.661523+02:00','565ce39e6b7ee011ac7d33d098b4466c6a588d14ed0f7fdfa0143c61f59809c3','{"name":"Dumbbell Rear Lunge","instructions":"This exercise involves holding a dumbbell in each hand and stepping back into a lunge position, then returning to standing. It primarily targets the glutes, hamstrings, and quadriceps.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1651/","author":"AlucardEvil40","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:d420baf8-977b-499e-8f91-416374227b91','wger-english-2026-09-08',1602,'2026-06-19T18:54:36.570349+02:00','aaf948bb3071661329a68711c567eb030ca43ae0bc1f26d11dd2766a12c9500d','{"name":"Dumbbell Scaption","instructions":"Starting position: Stand upright with your feet shoulder-width apart. Hold a dumbbell in each hand with a neutral grip (palms facing each other). Keep a slight bend in your elbows, shoulders relaxed and shoulder blades pulled back. Execution: Slowly raise the dumbbells forward and slightly to the side, at about a 30–45° angle from your body (between a front raise and a lateral raise). Lift until your arms are about shoulder height (do not go overhead). Pause for a second at the top and feel the activation in your shoulders and scapular stabilizers. Lower the dumbbells back down under control to the starting position. Breathing: Inhale as you lower the dumbbells. Exhale as you lift them. Common mistakes: Using dumbbells that are too heavy (causing jerky movements). Lifting above shoulder height (puts unnecessary stress on the shoulder joint). Arching the lower back instead of keeping the movement controlled at the shoulders. Purpose of the exercise: Activates the lower trapezius, serratus anterior, and scapular stabilizers. Helps correct posture and improve shoulder balance.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1602/","author":"zdelko","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:5a9f4fa4-6b71-4bc7-a284-e76e43e3106a','wger-english-2026-09-08',1429,'2026-06-19T18:52:35.140968+02:00','103871d3675ce4312d404ee266f05c5b5ff3e3493eb2a3e4a7573d996b53325f','{"name":"Dumbbell Shoulder Rotations","instructions":"Dumbbell shoulder rotations are designed to strengthen the rotator cuff muscles and improve shoulder stability and mobility. External Rotation : Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm outward, away from your body, keeping your elbow stationary. Slowly return to the starting position. Internal Rotation : Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm inward, toward your body, and slowly return to the starting position. Perform the exercise with controlled movements to avoid strain.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1429/","author":"hpmbala@gmail.com","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:3e9b3bb0-7958-4836-89a5-ed0c5f7eeb03','wger-english-2026-09-08',1650,'2026-06-19T18:49:36.273254+02:00','a15762ae78da5d1740b0e3f2131b2822f67326b4f42cb885de023e0adc6215d8','{"name":"Dumbbell Side Bend","instructions":"This exercise involves holding a dumbbell in one hand and bending sideways to work the oblique muscles on the side of the body. It can be done standing or seated and is often used as a core strengthening exercise.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1650/","author":"AlucardEvil40","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:73dbe7a5-e8f3-48fd-814e-bc3378c15be2','wger-english-2026-09-08',1286,'2026-06-19T18:51:17.417389+02:00','3ebbb80fa728080405ea2240e4765959a30d39c4587349e7db02be37b69a68e4','{"name":"Dynamic Planche","instructions":"Start in a plank position, with your hands directly under your shoulders and your feet hip-width apart. Engage your core to keep your body in a straight line from head to toe. From this position, bend your knees slightly and jump with both feet inward, bringing them as close to your core as possible As soon as your feet touch the ground, push off forcefully to jump again and return to the starting plank position. Continue repeating this jumping motion, maintaining control and core stability throughout the exercise. Make sure to keep your breathing steady while jumping, breathing deeply and controlling your breathing. Keep your gaze fixed on the ground to maintain proper spinal alignment. Repeat the jumps for the desired length of time or the number of repetitions recommended for your workout program. To finish the exercise, rest by releasing the plank position, then stretch if necessary to loosen your muscles.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1286/","author":"painDpice","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:45d89ca5-f5c7-4e56-9833-fd160cd2666d','wger-english-2026-09-08',1099,'2026-06-19T18:49:47.210603+02:00','87703df1c828e2ca49190299fffe5dc526b30ca39ac150d6afc7d152134bcdb5','{"name":"Dynamic side hold","instructions":"Sling a rubber band on a kettlebell and lift the kettlebell by the rubber band. Let it hang by your side and stand on one leg, switch leg while continuing hold. Repeat with other hand","equipment":["Kettlebell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1099/","author":"philip","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:81c6b9ef-7cb7-4328-8cb4-47ae8ecc42be','wger-english-2026-09-08',1288,'2026-06-19T18:51:20.162823+02:00','d75df0f3ec2341f7af8f8950d5370df32bf812b418bce376c761933ad48d8ee5','{"name":"Dynamic side plank","instructions":"The dynamic side plank involves positioning yourself on your side, supported on one elbow and the side of your foot, then dipping your hips up and down while keeping your body in a straight line.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1288/","author":"painDpice","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:ddf4111d-907d-4d6c-b583-58323b96ca03','wger-english-2026-09-08',2480,'2026-07-22T07:50:12.974243+02:00','bf7c1374ff395d604a6a9fac663045c9a9b22d9e70f3d57ec2acbaa26fc9ac65','{"name":"Easy Continuous Swim (Freestyle)","instructions":"Swim freestyle at a relaxed, steady pace without stopping — think conversation pace, not racing. Focus on smooth, even strokes rather than speed or breathing technique; this is just to get your body moving and your heart rate up.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2480/","author":"Imported from swim plan","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:1d1a53dd-e00f-477e-83f7-09c8ef9a71cd','wger-english-2026-09-08',2531,'2026-08-18T11:46:41.998403+02:00','3809369407e8da870d396eb6a9345be96186252ef093fcd05ef8570c27c0a4e6','{"name":"elbow lever","instructions":"​A calisthenics static balance skill where the entire body is held straight and parallel to the ground, supported by tucking the elbows firmly into the abdomen or pelvic bones.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2531/","author":"ege","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:302e02df-4270-4a0b-8c5d-b743cdb06fc9','wger-english-2026-09-08',1027,'2026-06-19T18:49:15.850274+02:00','fb7dbd14ff1578cf37ad03c9bd98cd4857cb7924fbf01e1ca9ee7ca9e76c79f5','{"name":"Elevated prayer stretch","instructions":"Starting position: Kneel in front of a bench, far enough so that your torso can fit between your knees and the bench. With your back straight, place your elbows on the bench, with palms together, hands pointing up. Steps: On exhale, stretch your chest down toward the floor without moving your lower back. At the same time, bring your hands toward your shoulders, keeping palms together and elbows on the bench. Hold for a few seconds. On inhale, relax your back to return to the starting position. Repeat.","equipment":["Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1027/","author":"tinman","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:95a300de-2ad8-492e-9364-13766d9e7618','wger-english-2026-09-08',962,'2026-06-20T00:48:33.875488+08:00','4122e01210eeeb8feb0c237f309a21d553b535ba8ebee89a09f8950fcf395740','{"name":"Elliptical","instructions":"It improves muscle toning, strengthens the leg muscles (quads, glutes, calves), helps vascularisation and increases resistance. The elliptical is also very useful if you aim to lose weight. Teste","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/962/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:253813a0-b33f-48b3-991e-ca66116e053f','wger-english-2026-09-08',2529,'2026-08-18T11:27:54.932384+02:00','3b8b0c487af3b55141009c3c5ee56e4379ef57ce282515f9c9121c9de48b5cbb','{"name":"explosive push ups","instructions":"Explosive Push-Ups Start in a standard push-up position, lower your chest, then explosively push off the ground so your hands leave the floor. Land softly and immediately repeat.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2529/","author":"ege","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:a4413bcc-dcd1-4332-a09a-fee94a265e22','wger-english-2026-09-08',1835,'2026-06-19T18:55:47.628361+02:00','cf9c94b0521a65be084bb2b6aa262aa79475db77ee799f6cf874370079e7b482','{"name":"External Rotation Stretch","instructions":"Sit with your feet pressed against each other, and one knee raised all the way out to the side of your body. Place your elbow on your raised knee, bend it at 90 degrees, and point your hand directly forward, holding your barbell/dumbbell. Keep your shoulder depressed and retracted, raise your hand until your forearm is vertical, as if you were about to wave at someone like a robot. Lower your hand to the original position and repeat.","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1835/","author":"Croak6728","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:52093ce1-2544-4b48-ad15-6e02de9b576d','wger-english-2026-09-08',2503,'2026-08-10T03:39:28.348691+02:00','f7c88c1edad6186220d328263e6fa6bf34be6db9059457237eb4474e1c373978','{"name":"Face Pulls (Bodyweight Doorframe/Towel)","instructions":"Vasco custom face pull variation using doorframe or towel for rear delt development. Zero equipment. Part of Tuesday Pull day.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2503/","author":"Vasco Custom","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:7bf4e131-d4a3-44c0-8fca-9e10002492e7','wger-english-2026-09-08',1732,'2026-06-19T18:55:01.350146+02:00','b8093acb2529f89a316dacd64056f93cb017ed446a1413a80e97938aa0fbf1ae','{"name":"Face pulls with yellow/green band","instructions":"Face pulls with band – standing horizontal pull. Grab the band at face height, pull elbows high and wide towards your face while squeezing shoulder blades together. Trains upper back, rear shoulders and improves posture.","equipment":["Resistance band"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1732/","author":"54str","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:d7a418d4-d0cb-4f85-8a7c-1e9d97152cbd','wger-english-2026-09-08',222,'2026-07-23T12:36:14.828136+02:00','c0e245f0f9d3fa5dbc69cf3b2210f81087efd4086ec5346936ce76e761292efa','{"name":"Facepull","instructions":"Attach a rope to a pulley station set at about chest level. Step back so you''re supporting the weight with arms completely outstretched and assume a staggered (one foot forward) stance. Bend the knees slightly for a stable base. Retract the scapulae (squeeze your partner''s finger with your shoulder blades) and pull the center of the rope slightly up towards the face. A good cue is to think about pulling the ends of the rope apart, not just pulling back. As you near your face, externally rotate so your knuckles are facing the ceiling. Hold for one second at the top position and slowly lower.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/222/","author":"abeworld","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:03f7fc27-e64f-4417-ab0c-a52adac60fda','wger-english-2026-09-08',1694,'2026-06-19T18:53:44.237251+02:00','7abd9860eea816b91c6af3b2dd9dae525f54839be99451f7cd2ccf091eb0d32a','{"name":"Flat Machine Press","instructions":"Execution Start position: Elbows bent at roughly 90°, hands just outside your chest. Keep wrists straight and aligned with your forearms. Pressing phase (concentric): Push the handles forward until your arms are almost fully extended — don’t lock out. Focus on squeezing your chest at the end of the movement. Returning phase (eccentric): Slowly bring the handles back toward your chest, feeling the stretch in your pecs . Maintain tension — don’t let the weight stack touch down between reps.","equipment":["Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1694/","author":"daiben","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:fdc550b6-ec58-4023-ba62-b54045e9a10d','wger-english-2026-09-08',235,'2026-06-19T18:56:52.897540+02:00','74483244803b860546fbaa87d3fb578d3f32e24f5064e3c9b8509b9090823eea','{"name":"Flutter Kicks","instructions":"-Laying on the back, lift your straightened legs from the ground at a 45 degree angle. -As your Left foot travels downward and nearly touches the floor, your Right foot should seek to reach a 90 degree angle, or as close to one as possible. -Bring your R foot down until it nearly touches the floor, and bring your L foot upwards. Maintain leg rigidity throughout the exercise. Your head should stay off the ground, supported by tightened upper abdominals. -(L up R down, L down R up, x2) ^v, v^, ^v, v^ = 1 rep -Primarily works the Rectus Abdominus, the hip flexors and the lower back. Secondarily works the Obliques. Emphasis placed on the lower quadrant of the abs.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/235/","author":"nate303303","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:95d226ad-3bf7-4cd6-aa64-2f26b526d8b6','wger-english-2026-09-08',238,'2026-06-19T18:46:35.176852+02:00','a8eae03da257f5d711347e7818e0e86d391e56137faa347b04ece737ed777eeb','{"name":"Fly With Dumbbells","instructions":"Take two dumbbells and lay on a bench, make sure the feet are firmly on the ground and your back is not arched, but has good contact with the bench. The arms are stretched in front of you, about shoulder wide. Bend now the arms a bit and let them down with a half-circle movement to the side. Without changing the angle of the elbow bring them in a fluid movement back up.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/238/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:55d0a5ec-b147-40c3-aa77-314e61c93689','wger-english-2026-09-08',239,'2026-07-23T12:08:36.039336+02:00','f3aefb398587fb2f66c1e1a2d82b151745fbf63b0302959ff685feb531f8ee76','{"name":"Fly With Dumbbells, Decline Bench","instructions":"The exercise is the same as with a regular bench: Take two dumbbells and lay on a bench, make sure the feet are firmly on the ground and your back is not arched, but has good contact with the bench. The arms are stretched in front of you, about shoulder wide. Bend now the arms a bit and let them down with a half-circle movement to the side. Without changing the angle of the elbow bring them in a fluid movement back up.","equipment":["Bench","Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/239/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:0c6764f2-fb86-43f1-bd35-04a35f74d5e4','wger-english-2026-09-08',2507,'2026-08-10T07:09:59.048564+02:00','1126e628d87c477b2c4f1fad1c66a80d0ca9c1e4357d481ff95e3ae5f89e3dae','{"name":"Forearm Plank (Core L1)","instructions":"Vasco custom forearm plank - foundational anterior core stability exercise. Teaches full-body tension, breath control, and anti-extension. Prerequisite for all advanced core work.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2507/","author":"Vasco Custom","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:00eae665-ff78-4373-9c43-f44a4a1b43e0','wger-english-2026-09-08',1238,'2026-06-19T18:50:52.948846+02:00','209479ade92dfd520dec9adb033aa93c7b18be693337faf20e2d8ca98dd50b6e','{"name":"Frog stand","instructions":"Starting position: Stand with your feet shoulder-width apart and your toes pointing forward, facing a wall or bench for support if needed. Bend your knees into a squat position. Place your hands on the ground in front of you, shoulder-width apart, with your fingers spread wide. Make sure your elbows are under your shoulders and your body forms a straight line from your head to your heels. Upward phase: Push with your feet and hands to lift your body off the ground. Straighten your legs and arms, keeping your body aligned. Engage your core and glutes to maintain the position. If needed, rest your knees on the wall or bench for assistance.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1238/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:f41ac754-45a0-443b-afe5-e624e215229f','wger-english-2026-09-08',1245,'2026-04-15T22:23:54.024800+02:00','5071d57ad0177f4042398660ab7c71a1ac89fb9250273638a96ce62e2453f01c','{"name":"Front Lever","instructions":"The front lever is a figure where the body is kept in a horizontal position parallel to the floor.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1245/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b61dff58-6e47-4671-853b-208e7cd0ced4','wger-english-2026-09-08',1252,'2026-04-15T22:23:54.026608+02:00','628fdc68c5bee2794d35b45d31596cff7a79e2624bb3789c3723e39206e1465b','{"name":"Front lever pull-up","instructions":"in the front lever position, with legs extended or easier if collected, pull by bringing the chest closer to the bar.","equipment":["Pull-up bar"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1252/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:e79616cb-f5fb-4b10-b99d-09d43774e142','wger-english-2026-09-08',1214,'2026-06-19T18:51:03.824793+02:00','55d06f7d6d504d948955c543945e98020cb19d3fd558cffdc00f61b5b374038b','{"name":"Front lever tuck","instructions":"The muscles involved in the Front Lever, most subjected to stress, are mainly the extensors such as: the latissimus dorsi, the teres major, the posterior deltoid and the long head of the biceps.","equipment":["Pull-up bar"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1214/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:dd9dcfd2-879f-422a-ad06-d2c187c58d1f','wger-english-2026-09-08',1307,'2026-08-27T18:06:27.988735+02:00','4321e863218e9814bca9fde12aad0594e3e7968eb890d19b1618eafe5e98e4b3','{"name":"Front Plank","instructions":"The plank is a bodyweight exercise. As a multi-functional movement, the plank not only targets your abdominal muscles but also the spine and hip. Plank strengthens and tightens your entire body, improves your posture and balance, reduces body fat, and can help boost your metabolism. Exercises such as the “plank pose” help strengthen the stamina of stabilizing abdominal muscles. It can also help relieve back pain associated with a weakening of the function of the stabilizing muscles of the body. Planks are a versatile exercise that targets many of the most important muscle groups in the body, so they can be applied by anyone to improve endurance and overall body strength.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1307/","author":"hektkaso","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:be9dfe16-9fc3-463d-a9cd-7aade27ef571','wger-english-2026-09-08',1731,'2026-07-23T12:36:46.800583+02:00','3dc59f904c1d47999276e342a84a0633d87bd5946f22923a44e16efff9f08267','{"name":"Front Raise (Cable)","instructions":"Raise the handle in a slight arc with controlled movement. Don’t swing your torso to start the rep.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1731/","author":"barry","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:9c35594c-bbcc-4656-bdcb-376814c90e96','wger-english-2026-09-08',256,'2026-06-19T18:46:37.707561+02:00','9c5cff41141059c611d40a106d5694b2483bd5ecd7461a5c0cf8e53349f8c57d','{"name":"Front Raises","instructions":"To execute the exercise, the lifter stands with their feet shoulder width apart and weights or resistance handles held by their side with a pronated (overhand) grip. The movement is to bring the arms up in front of the body to eye level and with only a slight bend in the elbow. This isolates the anterior deltoid muscle (front of the shoulder) and uses the anterior deltoid to lift the weight. When lifting it is important to keep the body still so the anterior deltoid is fully utilised; if the weight cannot be lifted by standing still then it is too heavy and a lower weight is needed. It is important to keep a slight bend in the elbow when lifting as keeping the elbow locked will add stress to the elbow joint and could cause injury. A neutral grip, similar to that used in the hammer curl, can also be used. With this variation the weight is again raised to eye level, but out to a 45 degree angle from the front of the body. This may be beneficial for those with shoulder injuries, particularly those related to the rotator cuff.","equipment":["Barbell","Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/256/","author":"Manu, wikipedia","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:68e0dbba-2d1e-4a56-8378-8824c1de3342','wger-english-2026-09-08',254,'2026-07-02T16:14:31.093816+02:00','b67997823d8c59bca0c144b90f448bd3a9a3417b73e4d72eb7f3dda326e0031d','{"name":"Front Raises with Plates","instructions":"The plate front raise is a variation of the dumbbell front raise where the lifter holds a weight plate between two hands, rather than using a dumbbell, barbell, or other weight. It can provide variety in a shoulder-focused muscle-building workout, or as part of an upper body or full-body circuit. While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip : The arms will remain in this position throughout the exercise. This will be your starting position. Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. As you inhale, slowly lower the plate back down to the starting position. Repeat for the recommended amount of repetitions.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/254/","author":"Marius","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:e5a62151-5350-4c86-8a19-3e9ca7bf0f38','wger-english-2026-09-08',260,'2026-06-19T18:50:23.358527+02:00','935b98b96452b0f7117e425b19f4b9dfeef8457dbd967561be811f3431c041db','{"name":"Full Sit Outs","instructions":"(A) Get in high plank position on your hands and toes.(B) Shift your weight to your left hand as you turn your body to the right; bend your right leg behind you and extend your right arm up. Return to the center and repeat on the opposite side. Continue, alternating sides. Make it easier: Don’t raise your arm after you bend your leg behind you. Make it harder: Balance with your arm and leg extended for two counts.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/260/","author":"http://www.realsimple.com/health/fitness-exercise/","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:7f942691-2a01-4675-9e3a-409105d5f2bf','wger-english-2026-09-08',1592,'2026-06-19T18:54:29.705555+02:00','fe0a490b2b3d17e519814f2b82bac3e240668522fe3df63c925b6a28df86f3bc','{"name":"Guided or free meditation","instructions":"A mental mindfulness exercise that helps reduce anxiety, improve focus and enhance overall well-being.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1592/","author":"MrAlfaRobot","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:35008ce6-74ca-40db-b965-44a1eccfa061','wger-english-2026-09-08',1516,'2026-04-15T22:23:54.121975+02:00','3e6de347819c99828960932bf6edf2327791a10179811f868bd615dcc5167817','{"name":"Handstand","instructions":"Handstand free standing by pressing arms into the ground and contracting core and glutes","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1516/","author":"Fittness69","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:cfe3f20e-d078-4e6c-91fc-37da62f5ac0a','wger-english-2026-09-08',1411,'2026-06-19T18:52:30.207070+02:00','f076009d35deb9228e69baa7900fab30222276013cd50854ecbc7bcd3a5b6013','{"name":"Heel Touches","instructions":"Starting Position: Lie on your back on an exercise mat. Bend your knees, keeping your feet flat on the floor and hip-width apart. Place your arms along your sides, palms facing inward, just off the floor. Engage Core: Lift your head, shoulders, and upper back slightly off the ground. Keep your neck neutral and chin slightly tucked. Perform the Movement: Side-bend to the right, reaching your right hand toward your right heel. Return to the center, then side-bend to the left, reaching your left hand toward your left heel. Continue alternating sides in a controlled manner. Breathing: Exhale as you reach toward your heel and inhale as you return to the center.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1411/","author":"hpmbala@gmail.com","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:e781dae5-90b8-4105-8aa6-82d278ac5ff5','wger-english-2026-09-08',1303,'2026-06-19T18:51:31.694953+02:00','5a471d4aa6f90b30329706fe3877f47df753937e8b8c49db57e3b09167443732','{"name":"Helms Row","instructions":"Setup: Place your chest on the end of a bench, using a towel or anything soft to keep your chest protected. You want your chest to be in contact with the bench around the nipple line. Your back should be almost parallel to the floor Execution: When you’re starting the exercise, focus on pulling your elbows back until you feel maximum tightness in the lats. If you want to get some trap activation with the exercise, relax your shoulder blades when the weights are hanging down and then retract them as you start the rep.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1303/","author":"carlos3c","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:47b244f0-ebc6-4498-9d9f-7e7bff47322e','wger-english-2026-09-08',1882,'2026-07-23T12:36:50.466306+02:00','ef11c897b8ae831dd8fa8485670e5fceabac033e11a85c7a78077769175392c8','{"name":"High-Cable Lateral Raise","instructions":"Stand next to a cable machine with the pulley set to waist height. Grab the opposite-side handle with the hand farthest from the pulley, keeping your palm facing in. Keep your core engaged, chest lifted, and shoulders relaxed. Maintain a slight bend in the elbow throughout the lift. Lift your arm out to the side until your elbow reaches shoulder height, keeping your wrist aligned with your elbow. Briefly pause at the top, then slowly lower the handle back to your side with control. Repeat for the desired reps.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1882/","author":"Deflation","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:3edbb63e-f326-4bd0-8af3-2d5deabb864f','wger-english-2026-09-08',285,'2026-06-19T18:48:42.064032+02:00','0ff8f755f5fc63dbd5eb6866475d1d43cbf6cad6b4c40eb4d02a4409eb87afd4','{"name":"High Knee Jumps","instructions":"Start with legs slightly wider than shoulder width Drop into a bodyweight squat As you hit the bottom of the squat, explode upwards into a jump while simultaneously tucking your knees into your chest midflight. Remain tucked until the apex of your jump. Land on both feet, making sure your knees are not locked so as to avoid excessive strain upon your joints. Collect yourself into the next rep as quickly but under control as possible.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/285/","author":"nate303303","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:32942c8c-0572-4d8b-9aec-48cb026fda1f','wger-english-2026-09-08',1318,'2026-06-19T18:51:41.773642+02:00','25947693bc34733f5534addcc322fc0a50502fd23361ac7465d2be046c26363f','{"name":"High Knee Skips HD","instructions":"You can use this exercise both as a dynamic warm-up before training and add it to your cardio training routine to burn fat. High knee skips are a plyometric exercise. Plyometrics are explosive aerobic moves that increase speed, quickness, and power and they work your whole body. High knee skips target the oblique, leg muscles, hip muscles and hip flexors and also work on the thighs, knee tendons, quadriceps and shoulders. Jumps are beneficial to your health because they combine cardiovascular conditioning with strength work. Since jumps elevate your heart rate, they can also improve your cardiovascular fitness.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1318/","author":"hektkaso","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b526b17b-408d-4da2-8940-ceaf9dae9d93','wger-english-2026-09-08',289,'2026-06-19T18:48:45.398270+02:00','7e57a779375434c3bb081ec5e4c977b8dcc7970b2a62fa22ff7dc4cac31ca585','{"name":"High Pull","instructions":"Use a light barbell, perform explosive lift up starting from underneath knee cap level. Lift/raise explosively using hips, at shoulder level. Tempo: 2111","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/289/","author":"Mahoney","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:e87b76b8-2960-4225-9146-47f78bf8c630','wger-english-2026-09-08',1137,'2026-07-23T12:36:27.178324+02:00','ac6fc4efde718153ce36ec752af36ac97f8cbd0c158e0ab8ce7d13b9445fae91','{"name":"High-pulley pullover","instructions":"Stand facing the machine, feet slightly apart, gripping the bar with an overhand grip, arms extended, hands shoulder-width apart. Keeping your back fixed and your abdominal muscles contracted, inhale and bring the bar down to your thighs while keeping your arms extended (or your elbows slightly bent). Exhale at the end of the movement.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1137/","author":"Franpol","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:f80468f2-7c5d-45c5-9470-46a88c1a75c2','wger-english-2026-09-08',1492,'2026-07-23T12:36:34.970783+02:00','1064883b1e84038abc2f681bd0acd94074327dc888329d8d42e345e1b91c5ef3','{"name":"High Row","instructions":"Kneeling down on one leg and pulling cable down while driving elbow into the lats.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1492/","author":"aahuja","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:476c1d96-6590-4f86-98f0-3f12808fab53','wger-english-2026-09-08',1080,'2026-06-19T18:49:17.896879+02:00','769b99aec04c967eb287f97707fc197278afc8744d9d83c8d9254540a6fe8d42','{"name":"Hindu Pushups","instructions":"Exercise to strengthen the shoulders and pectorals. Its name is due to the fact that it begins in the Yoga position \"Dog Facing Down\", passing to \"Cobra\" but without resting the legs or torso on the ground to finally end with a normal flexion. The exercise can also be performed backwards (back to the starting position). As a variation, after doing the push-up, the hip can be raised to return to downward facing dog.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1080/","author":"Imobard","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:541941e0-0fa5-4474-a382-9baf04948f8d','wger-english-2026-09-08',292,'2026-07-23T12:24:56.343999+02:00','5b744345814a31e3825dd6241d3a9e00006a73d10d3e7876ced97a3f94f5bc7a','{"name":"Hip Raise, Lying","instructions":"Lying down on your back, with your feet flat on the floor. Raise your hips up evenly as high as you can and hold for as long as you can.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/292/","author":"James Mackay","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:2b165c5c-403f-43e5-b28d-83c8b914505b','wger-english-2026-09-08',2510,'2026-08-10T08:14:08.765720+03:00','0924060716df3c6e2544533160221c4b508c3f0e7801c12d8a9e049ee0f76c3d','{"name":"Hollow Body Hold (Core L1)","instructions":"Vasco custom hollow body hold - foundational anti-extension core stability. Teaches global anterior chain tension, breath control under load, and positional awareness for gymnastics/calisthenics.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2510/","author":"Vasco Custom","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:ca4c8872-e53c-47ca-bc33-448b9ba9360f','wger-english-2026-09-08',1712,'2026-06-19T18:54:35.223755+02:00','c6bd968a3ad6b22e89488f7023845aa93fb22cf40a2d26bdda1c82f343638aa3','{"name":"Horizontal Shoulder Flexion Stretch","instructions":"Raise your arm out to the side, placing your hand on a wall or doorway beside you at shoulder height Turn your body away from your arm to stretch the chest, as far as is comfortable","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1712/","author":"Croak6728","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:ebe7d74b-78a8-4757-9310-6fb22b23aa58','wger-english-2026-09-08',1487,'2026-06-19T18:53:19.114910+02:00','4b8e9c725b019358254fdd0cc2efdcc97896487a238204f5a359f7e22bc7397a','{"name":"Hyper Y W Combo","instructions":"Use a glute-ham raise or a stability ball for this exercise and a light weight plate in each hand. Raise your torso to form a straight line with your legs and raise the arms outward slightly beyond a 90-degree angle into a W position to hit the rotator cuff muscles, and then lower back to the starting position. Then raise up again with arms in a Y position to activate the lower traps.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1487/","author":"Moffi","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:37f6bd56-815a-4975-99af-05e749fae4b2','wger-english-2026-09-08',301,'2026-08-27T18:20:03.029383+02:00','7e3d3a2f674f83283018606b8174b402381faf89f45426dd70e08a93713ab061','{"name":"Hyperextensions","instructions":"Lie on the hyperextension pillow with your navel at the front edge, allowing your upper body to hang freely. Tighten all your back muscles and raise your torso until you''re horizontal, but no higher. Lower yourself slowly, maintaining a steady flow of muscles.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/301/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:662b9911-fa55-4564-b830-fdb6a046b162','wger-english-2026-09-08',1248,'2026-06-19T19:55:05.260411+02:00','d13dd8d0db4fd00b6dd676a88dcd29a3d8c8fdc12a41f749df117e4c45dcdf2c','{"name":"Ice cream maker","instructions":"From the final phase of a pull-up, we push ourselves back with our shoulders until we reach the front lever position. From there, we pull ourselves back up to the starting position.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1248/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:57e17672-52b9-43cf-8d0d-4b3f06a0c0d0','wger-english-2026-09-08',537,'2026-07-02T16:44:43.088138+02:00','9e2dc755442c304a3fcd48240304fe9689e23003b7e9073e552a76c0306e5d78','{"name":"Incline Bench Press - Dumbbell","instructions":"This is a variation of the flat bench press designed to emphasize the clavicular head of the pectoralis major (the upper portion). By tilting the torso, the angle of the push changes, shifting more tension to the upper chest and shoulders, which helps achieve a more aesthetic, balanced, and three-dimensional development of the torso. Bench Adjustment and Preparation: Set the bench to an incline of between 30 and 45 degrees (an incline greater than 45° will place too much strain on the shoulders and reduce the stimulus to the chest). Sit down with a dumbbell on each thigh. Starting position: Lean back, resting your back against the bench, while using your knees one after the other to push the dumbbells upward to shoulder height. Anatomical Stabilization: Plant your feet firmly on the floor. Retract your scapulas (bring your shoulder blades together and press them into the bench) to protect your shoulders and stabilize the load. Eccentric Phase (Lowering): Lower the dumbbells slowly and in a controlled manner toward the upper part of your chest. Your elbows should not splay out to the sides (90°); maintain a safe angle of about 45 to 60 degrees relative to your torso. Concentric Phase (Lift): Push the dumbbells vertically upward as you exhale. Follow a slightly converging path (without letting them touch at the top). Stop the movement just before locking out your elbows to maintain muscle tension in the upper pectoral.","equipment":["Dumbbell","Incline bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/537/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:4e941b0d-4b2f-4393-89cf-6a5e9b69252e','wger-english-2026-09-08',1138,'2026-07-23T12:36:27.586129+02:00','12172e4a904d7e30e46ac6ffddb24dbfde53e19fd5d4d00271652724aa7909e5','{"name":"Incline bench pulldown","instructions":"Lying face down on the incline bench facing the cable machine, perform the pulldown.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1138/","author":"Franpol","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:70c99a4e-3340-4993-a7f1-2d2709dada1a','wger-english-2026-09-08',828,'2026-07-23T12:08:36.445040+02:00','27a2d6a4645dcf333544420b1210267953f3687e5c76738cb4b77a19618d93a6','{"name":"Incline Bench Reverse Fly","instructions":"The incline dumbbell reverse fly is an upper-body exercise targeting the posterior or rear deltoids, as well as the postural muscles of the upper back. Because it targets such small muscles, this exercise is usually performed with light weight for high reps, such as 10-15 reps per set or more.","equipment":["Dumbbell","Incline bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/828/","author":"cshep442","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:51a2d520-b510-4b6e-bd65-9fc40365e8de','wger-english-2026-09-08',1283,'2026-06-19T18:51:14.694651+02:00','290be76176ffa3580dae860dda1e9de08463f553c64b2065f6af2af46fc68548','{"name":"Incline Chest-Supported Dumbbell Row","instructions":"Set up an adjustable bench at a 45-degree angle. Lay on your stomach with your head hanging just above the edge of the bench. Grab a dumbbell in each hand and set up with a good posture – core and lats engaged and shoulders neutral. Row the dumbbells toward the top of the stomach and squeeze the back at the top of the rep. Finally, lower the dumbbells back to the starting position and repeat until all reps are completed.","equipment":["Bench","Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1283/","author":"carlos3c","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:7de7b8a8-313d-465f-bb22-8527ae45110a','wger-english-2026-09-08',171,'2026-06-19T18:46:28.995282+02:00','284ce848450b0349d8560aae89ac269d9040825dd52a6aed915a5f9ad1818132','{"name":"Incline Crunches","instructions":"Lay down on your back on a inclined bench, feet are on one end of the bench. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back.","equipment":["Incline bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/171/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:16bd91ca-a9fe-47fc-b3a8-a9d70549e929','wger-english-2026-09-08',1879,'2026-06-19T18:55:53.946189+02:00','6fd5aab16384c249e6a13a2c936cb170b46517e34e41c3bcd268f0f4e47b690e','{"name":"Incline DB Y-Raise","instructions":"Set an incline bench to a 45-degree angle and sit facing the bench, chest against the pad, with a dumbbell in each hand, palms facing each other. Position your feet firmly on the ground for stability and let your arms hang down naturally with a slight bend in your elbows. Engage your core and keep your back straight throughout the movement. Raise your arms forward and out to form a Y shape, keeping the movement controlled and your elbows slightly bent. Lift until your arms are roughly parallel to the floor and in line with your ears. Pause briefly at the top of the movement to engage your shoulder muscles fully, then slowly lower your arms back down to the starting position. Ensure the movement is slow and controlled during both the ascent and descent to maximize engagement of the deltoids and supporting muscles. Repeat for the desired number of repetitions, maintaining proper form throughout.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1879/","author":"Deflation","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:55ff32e6-24ab-4303-9b50-176d60d48796','wger-english-2026-09-08',308,'2026-06-19T18:57:01.265947+02:00','2b7bccf39cfd7e1c71900fb82a766f2813bad736902f304b14bcd1f6ecf4dcea','{"name":"Incline Dumbbell Fly","instructions":"Use inclined bench. Hold dumbbells straight out to your sides, elbows slightly bent. Bring arms together above you, keeping angle of elbows fixed.","equipment":["Dumbbell","Incline bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/308/","author":"tuckerm","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:f89b3662-f911-4aab-9402-cfa6d47cea2b','wger-english-2026-09-08',1441,'2026-06-19T18:52:42.541704+02:00','e7aabc6ea5e130c57eb1c6d72e7bfbec4702a410699572f7eb81d87d5ef03c7b','{"name":"Incline OHP DB","instructions":"Sit on a bench with 45° incline Ellbows 45° out Move dumbbells down until upper arms are parallel to shoulders Move dumbbells up, meeting overhead","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1441/","author":"M9","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:2cc5644d-a8d7-49f5-8978-db0f2184864e','wger-english-2026-09-08',2499,'2026-08-10T03:36:46.520403+02:00','78339871a571e88b5e17fb35a66ce741b8ab077667eb13aa857cfb6754c2a556','{"name":"Incline Push-ups (Vasco L2)","instructions":"Vasco custom incline push-up progression for beginner home training. Bridges wall push-ups to floor push-ups. Part of Monday Push day.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2499/","author":"Vasco Custom","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:743690d3-dbfb-417a-a049-8b77fd5df31b','wger-english-2026-09-08',1716,'2026-06-19T18:50:34.913834+02:00','932f4e270a9b638e91bc77de3251e45de26db66309e8e0dc53f0226996bf6883','{"name":"Incline Shoulder Press Up","instructions":"Place your hands on the bench in a press up position Push your chest away from the bench to separate your shoulder blades Keeping your elbows straight , lower your chest towards the bench so your shoulder blades move closer together Push your chest away from the bench again","equipment":["Bench"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1716/","author":"Croak6728","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:88afb956-8d4a-45b3-8c7c-c23719316bfe','wger-english-2026-09-08',1693,'2026-06-19T18:53:42.635032+02:00','d1e3e6b86e1b2b7f4e73a71827f8f81fb2a4e6b1bf1b715c290476418f303f84','{"name":"Incline Static Hold","instructions":"Execution Hold Position: Lower the dumbbells a few inches above your chest — about the midpoint of a normal incline press. This is where your upper chest is under maximum tension. Static Hold: Hold the position for 20–45 seconds while keeping the chest tight. Breathe slowly but stay tense — do not relax your chest or shoulders . End the set: After the hold, carefully bring the dumbbells down and rest.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1693/","author":"daiben","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:8d56eb18-b000-41ff-8b31-c74df3a4b34b','wger-english-2026-09-08',1198,'2026-06-19T18:50:15.930446+02:00','7f435dc257e87fd08ce6e8a26f3c71ccb0903974d598efb132fcc267e2a366a9','{"name":"Inverted Rows","instructions":"Maintain a straight body, retract your shoulder blades, and pull your chest to the bar for an effective back and upper body workout.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1198/","author":"Gavru","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:2f5032de-df6d-406b-b709-9223ef5c3e24','wger-english-2026-09-08',314,'2026-06-19T18:48:54.874324+02:00','b2533c1117da926e5fe93cd3b18dcd68c304cacc6d0e27c54c2740bcbe39b5b8','{"name":"Isometric Wipers","instructions":"Assume push-up position, with hands slightly wider than shoulder width. Shift body weight as far as possible to one side, allowing the elbow on that side to flex. Reverse the motion, moving completely over to the other side. Return to the starting position, and repeat for the desired number of repetitions.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/314/","author":"cal.zabel","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:85c28424-ab47-40d4-9a27-e1b9bfb01e7c','wger-english-2026-09-08',1445,'2026-06-19T18:52:46.580318+02:00','bb26ff8aef3cadbcf3aa0fefb5a9f22820824a7761e9c69076a3d2f50ee7c71c','{"name":"Jerk OL","instructions":"Olympic lift jerk Hold bar in front on shoulders like push press Bend and extend knees pushing bar up while diving under the bar Catch bar overhead with straight arms using lunge Move feet parallel while holding bar in lockout","equipment":["Barbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1445/","author":"M9","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:89443e49-e5be-4b67-a5f6-e3f5ff80f6ea','wger-english-2026-09-08',1314,'2026-06-19T18:44:13.932783+02:00','1bfc9d20029f27b6ffd60130e90a112de1f18bb708af9e8233cefb92aced7aae','{"name":"Jumping Jack HD","instructions":"Jumping jack are a plyometric exercise. Plyometrics are explosive aerobic moves that increase speed, quickness, and power and they work your whole body. Jumping jack target the arm, shoulder, abdominal muscles, hip muscles and hip flexors and also work on the thighs, knee tendons and quadriceps. Jumps are beneficial to your health because they combine cardiovascular conditioning with strength work. Since jumps elevate your heart rate, they can also improve your cardiovascular fitness.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1314/","author":"hektkaso","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:57d1a6fc-fc28-43a7-9beb-0e851a47a976','wger-english-2026-09-08',2481,'2026-07-22T07:50:16.826173+02:00','345f90a863aed8656a9468b3f4c4c236d38cf3c0ed74fdbafc0ac0f6cfced8f6','{"name":"Kick with Board","instructions":"Hold a kickboard with both hands, arms extended in front of you, face in the water (lift head forward to breathe when needed). Kick from your hips, not your knees, keeping your legs mostly straight with a slight bend and a steady, compact flutter kick. This builds leg endurance and keeps your body horizontal without needing to worry about your arms.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2481/","author":"Imported from swim plan","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b4e78b5a-6141-4fc9-a6f7-cba13ce6559b','wger-english-2026-09-08',1442,'2026-06-19T18:52:43.896178+02:00','0c13238307e724b6b3a45c095a39ba95e1d014ebdd1404d75a9dc2993855ea39','{"name":"Kreis Press DB","instructions":"Sit on a bench with 45° incline Hold dumbbells overhead Move dumbbells down as if doing overhead press Rotate dumbbells palms facing up and extend your arms in front of your body Move hands together until dumbbells meet, keep arms extended Reverse the motion until dumbbells are overhead again This is one repetition","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1442/","author":"M9","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:2d580008-4918-430a-b0bd-4fcfe8783195','wger-english-2026-09-08',2538,'2026-09-01T09:19:55.325668+02:00','06f38d97c6d2aa9e96ad0b16aadbff0f2dc5c48bf39c4c6da59ae6a30a42b04d','{"name":"Lateral Raise Isometric","instructions":"An isometric lateral raise is a shoulder exercise where you hold your arms out to the sides at waist height for a set amount of time instead of moving up and down","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2538/","author":"HexoctusEngineering","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:63375f5b-2d81-471c-bea4-fc3d207e96cb','wger-english-2026-09-08',348,'2026-06-19T18:46:42.325194+02:00','500b61a7fa976f5c01755b3e4e7a681232105bd4c79536c9b393a3cbefde3727','{"name":"Lateral Raises","instructions":"This exercise works the deltoid muscle of the shoulder. The movement starts with the arms straight, and the hands holding weights at the sides or in front of the body. Body is in a slight forward-leaning position with hips and knees bent a little. Arms are kept straight or slightly bent, and raised through an arc of movement in the coronal plane that terminates when the hands are at approximately shoulder height. Weights are lowered to the starting position, completing one rep. When using a cable machine the individual stands with the coronal plane in line with the pulley, which is at or near the ground.[9] The exercise can be completed one shoulder at a time (with the other hand used to stabilize the body against the weight moved), or with both hands simultaneously if two parallel pulleys are available.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/348/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:57263316-6f34-4539-952b-b07e09bac3ba','wger-english-2026-09-08',349,'2026-07-23T12:36:16.855997+02:00','421741a2e45d3b5dae80bf89e7bc3380a03d4fafe1a78fbdad0a2f5a31811ddf','{"name":"Lateral Rows on Cable, One Armed","instructions":"Set cable at waist height, start with arm across your belly and move han over and out too other side, one arm at the time.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/349/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:dac3c714-f0c6-4d97-8283-17be7dd77b65','wger-english-2026-09-08',351,'2026-06-19T18:57:00.552298+02:00','f92d0bc9f3e45a5755dd4e794b8d64de6182d7d321c3da1edde0d98e9cb0ec5f','{"name":"Lateral-to-Front Raises","instructions":"-(1) Perform a lateral raise, pausing at the top of the lift (2). -Instead of lowering the weight, bring it to the front of your body so that you appear to be at the top position of a front raise. You will do this by using a Pec Fly motion, maintaining straight arms. (3) -Now lower the weight to your quadriceps, or, in other words, lower the dumbbells as though you are completing a Front Raise repetition. (4) -Reverse the motion: Perform a front raise (5), at the apex of the lift use a Reverse Fly motion to position the weights at the top of a Lateral Raise (6), and finally, lower the weights until your palms are essentially touching the sides of your thighs (7). THIS IS ONE REP. (1) l front view (2) -l- FV (3) l- side view (4) l SV/FV (5) l- SV (6) -l- FV (7) l FV/SV","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/351/","author":"nate303303","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:ca514fad-c6ce-47b0-93a0-dc73a3507099','wger-english-2026-09-08',1603,'2026-04-15T22:23:54.570567+02:00','a6874765170ed9707cd3e8dbc2c45071166ba086c5e338d27055c3ac6eda1940','{"name":"Leg curl with elastic","instructions":"Standing position: Place the band under your feet in the middle of your foot and grasp it with a hammer grip.","equipment":["Resistance band"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1603/","author":"clafal","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:82aec7f9-ee03-4b24-8994-f6bde07c6a41','wger-english-2026-09-08',379,'2026-04-15T22:23:55.118889+02:00','cfd8f25665d54cfcf532a238e7621a46c68d5ab7101592da22a2fe5058edbe51','{"name":"Leverage Machine Chest Press","instructions":"Be sure to adjust seat height so that the handles are towards the bottom of your pectorals.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/379/","author":"tuckerm","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:ac6e6a09-5175-4fea-9e56-e2ff3c00b0f2','wger-english-2026-09-08',1296,'2026-07-23T12:36:29.615130+02:00','a8ff2fbc53234f34d77e2c9c8827d32bf97dc8451d578129161527b06fc3a821','{"name":"Low-Cable Cross-Over - NB","instructions":"The low-cable cross-over is an isolation movement that uses a cable stack to target the upper portion of the pectoral muscles. It is common in upper-body and chest-focused muscle-building workouts, often in combination with presses or flyes from other angles to target all portions of the chest.","equipment":["Cable machine"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1296/","author":"JackSparrow","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:aa3b4ebe-6dee-45ad-a345-cf2acebf4159','wger-english-2026-09-08',406,'2026-06-19T19:55:09.109688+02:00','d4767424c2105dc1c4ba9681715b346e9a64fe4f98791d67ca46810e4ebc315e','{"name":"Lying Rotator Cuff Exercise","instructions":"This is an excercise for problems with the rotator cuff. Primary Infraspinatus, secondary Teres Minor. Lying on side. Keep elbow on waist and in 90 dgr angle. Rotate towards stomach. Add weight as fit.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/406/","author":"Trix","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:564dc73e-e8d4-4fd1-85ab-64dce4dd3ea0','wger-english-2026-09-08',1584,'2026-06-19T18:54:26.857036+02:00','531c64b6b332d10e79789c0f239b23fd2c90cd5046102aeb2b49b6de2c6c5938','{"name":"March or jog in place","instructions":"Low-impact cardiovascular exercise that simulates running without moving, ideal for warming up, improving endurance, or training in small spaces.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1584/","author":"MrAlfaRobot","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:2a1f7c0c-c63d-43f1-9934-a209ed405ff8','wger-english-2026-09-08',1915,'2026-07-23T12:08:34.425914+02:00','ae50b926a34792ab6e3d16b79ca4b39face088caee26b45e5787ae11f694793c','{"name":"Quadruped Hip Abduction","instructions":"Distribute your body weight evenly on all knees and arms. Keep the torso stable, with the abdomen engaged and the lumbar spine straight without twisting the back (imagine: a glass on your lower back won''t fall off). Raise one leg outwards without twisting it. Pay attention to the right angle at the hips and knees. Always train both sides of the body. To increase resistance, a resistance band can be used.","equipment":["Resistance band"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1915/","author":"treder","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:6705ec92-c6c6-4b2c-b919-bddb8177bf98','wger-english-2026-09-08',2486,'2026-07-22T07:50:20.861050+02:00','0bd8db93fee66de692487ab6f0684baaea91baf8425a1413707ebd05fcce0402','{"name":"Recovery Bobbing","instructions":"Same motion as the Bobbing Exhale Drill, but done in slightly deeper water (so you''re not touching the bottom) and at a slower, more relaxed pace — think of it as a recovery/reset exercise rather than a hard drill. Use it between harder drills to reset your breathing rhythm and calm down if you''re feeling rushed or out of sync.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2486/","author":"Imported from swim plan","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:12f88134-0f7a-4fb7-8bd9-436aa80d8b7c','wger-english-2026-09-08',1376,'2026-04-15T22:23:55.264891+02:00','2411953cbce5ae3f2fbd53395f0b19e1ad203e8580c22b9c800c9abb3eabf2f5','{"name":"Recumbent Bike","instructions":"For this exercise Recumbent Bike is needed. You just sit on it, set level and time and start the workout","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1376/","author":"pera_perkan","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:6995c30a-037f-4de3-ac4a-45384a1f38f9','wger-english-2026-09-08',1620,'2026-06-19T18:54:53.981469+02:00','f49d59c8db332bd3c6a6c83d0330224e21847b650daa0c078cc3bda408e20fa3','{"name":"Seated Dumbbell Calf Raise","instructions":"The seated dumbbell calf raise is a targeted exercise for strengthening the lower leg muscles. It follows the same movement pattern as the machine version: you place the weight on your knees, and by extending and flexing your ankles, you move the weight.","equipment":["Dumbbell"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1620/","author":"AlucardEvil40","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:6ec2d684-8091-4da9-8814-8a3052d0a302','wger-english-2026-09-08',2484,'2026-07-22T07:50:25.264149+02:00','9814f9122e518c7b6606b78e8f20e4e8732c215d078b24cbd466233a2d6a265e','{"name":"Side-Kick Breathing (Kickboard)","instructions":"Push off the wall on your side (not flat on your stomach), one arm extended forward holding the board or just extended, kicking continuously. Keep your head in a neutral position looking at the bottom of the pool, and when you need air, rotate your head sideways (one ear stays in the water, other faces up) to breathe, then rotate back to neutral. Swim a length like this, then repeat on the other side. This teaches the exact head position and rotation you''ll use once full stroke breathing comes in.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2484/","author":"Imported from swim plan","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:6e46833d-fd83-4c1a-90af-eb3f3a917199','wger-english-2026-09-08',590,'2026-06-19T18:47:00.068013+02:00','fc8e70de131b80406c85abfa2746f3f1cbe6b94f9185a7ea9d742d7e0eca80ce','{"name":"Sitting Calf Raises","instructions":"Sit on a bench for calf raises and check that the feet are half free and that you can completely stretch the calf muscles down. Pull your calves up, going as far (up) as you can. Make at the highest point a short pause of 1 or 2 seconds and go down.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/590/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:e29d9914-6b02-490b-8f3a-f9fe8f21993c','wger-english-2026-09-08',1526,'2026-06-19T18:53:49.657856+02:00','766fc131171e0fba22c92c45f9a720a463f0a291ce7a575270966f68eb5fd3fe','{"name":"Ski Machine","instructions":"Start standing on the platform with your feet hip-width apart. Reach overhead to grip the handles with your palms facing in. Soften your knees, then simultaneously drive your butt back as if you''re closing a door behind you while pulling your arms straight down past your hips until your hands pass by the side of your knees. Next, bring your arms back overhead while thrusting your hips forward until you''re standing with your arms fully extended. Repeat for reps, time or distance.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1526/","author":"flanny","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:e60125f0-3a88-4707-815f-fe0e2b4be3c4','wger-english-2026-09-08',595,'2026-06-19T18:49:10.425314+02:00','11156365834cfc21d13b020e0b51016315db63a410714408e7feb2aa4be125b2','{"name":"Skipping - Standard","instructions":"Do a single, double footed jump for each swing of the rope. Work on a smooth, rhythmical movement, bouncing lightly on the balls of your feet.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/595/","author":"Cerin","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:32cc7175-3fda-4c7e-900f-8766c22e3b2b','wger-english-2026-09-08',1523,'2026-06-19T18:53:45.587075+02:00','260824c715b285d5b055154b4d5ccf60ef5bba14cd87f34699c1ef2ff3436d04','{"name":"Sled Push","instructions":"Load the sled with 25% of your maximum load. If you don’t know this, choose a weight you can push for 10 minutes with short breaks. Beginners may choose to push the sled with no weight. Stand behind the sled and grab the poles with a high-grip hand position. Engage your core muscles and start pushing the sled forward as fast as you can, powering through your entire leg. Extend your hips and knees as you move the sled forward. Your foot stance should resemble your natural running position.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1523/","author":"flanny","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:b3e433ed-0247-46b3-be77-9f2738a09a48','wger-english-2026-09-08',1548,'2026-06-19T18:54:08.160751+02:00','57fe1805814144c8a0d1b09d131a13613f80637094ba0b0ae8f9d5afc8a88f8e','{"name":"Stair Master","instructions":"cardio and lower-body strength machine designed to simulate climbing stairs. It provides a low-impact, high-intensity workout that targets the legs, glutes, and core while improving cardiovascular endurance.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1548/","author":"MisterPinnacle","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:7ce443b6-eb84-4f65-b05f-461c1cc8bcc0','wger-english-2026-09-08',622,'2026-06-19T18:47:04.282658+02:00','0d39a83e7b2cffcd8a702ea04f8def0f39a67b6c27b4722a8aae5a443fd91ea0','{"name":"Standing Calf Raises","instructions":"Get onto the calf raises machine, you should able to completely push your calves down. Stand straight, don''t make a hollow back and don''t bend your legs. Pull yourself up as high as you can. Make a small pause of 1 - 2 seconds and go slowly down.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/622/","author":"wger.de","license":{"shortName":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}}}'::jsonb),
  ('wger:5da3d393-0c4e-4ac8-96b4-aab51f6ab3d1','wger-english-2026-09-08',1618,'2026-06-19T18:54:51.343314+02:00','4f94cfd41c0b494587eca80dd2fa0cc622e9d9de2d506fc72c51722a1ada3c0a','{"name":"Stationary bike cardio","instructions":"Benefits of Stationary Bike Cardio Stationary bike cardio is an excellent form of exercise that offers multiple benefits for health and well-being. Here are some of the most notable ones: Improved Cardiovascular Health Strengthens the heart: Regular exercise helps improve the heart''s efficiency and reduce the risk of cardiovascular disease. Increases circulation: It improves blood flow, which can help lower blood pressure. Calorie Burning and Weight Loss Efficient for burning calories: Depending on the intensity, you can burn between 400 and 600 calories per hour. Helps with weight loss: Combined with a balanced diet, stationary bike cardio can be effective for losing weight. Muscle Strengthening Tones the legs: It mainly works the leg muscles, including the quadriceps, hamstrings and calves. Improves muscular endurance: Over time, you can increase the endurance and strength in your legs. Mental Health Benefits Reduces stress: Exercise releases endorphins, which can improve your mood and reduce stress. Boosts energy: Regular physical activity can raise your energy levels and improve sleep quality.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1618/","author":"Tierrasverdes","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:2f10d91f-6c12-471b-bb9e-80840a56ce01','wger-english-2026-09-08',1962,'2026-06-19T18:48:14.713326+02:00','14c91d5b976247b32bea5f4f83073a0ade866f656771b16c98f06be09062e30c','{"name":"Step Jack","instructions":"The Step Jack is a low-impact plyometric-style move that provides cardiovascular benefits without the joint stress of jumping. It works the entire body, specifically targeting the legs, core, and shoulders. This move is ideal for beginners, individuals with joint sensitivities, or as a dynamic warm-up to gradually elevate the heart rate. Notes (Instructions): ​Stand upright with your feet together and arms at your sides. ​Step your right foot out to the side while simultaneously swinging both arms up above your head. Bring your right foot back to the center and lower your arms. ​Immediately repeat the movement, stepping out with your left foot. ​Continue alternating sides at a steady, rhythmic pace.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1962/","author":"Anon#2","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:1c17c370-dd74-46c4-b4f2-039c510af058','wger-english-2026-09-08',2485,'2026-07-22T07:50:28.845132+02:00','b9b4fb4038b5f6efb3993bd645efd62789447701a82de545f0a69d0d31d3d7fc','{"name":"Stroke-and-Roll Drill","instructions":"Push off, swim a few strokes, and every breath roll fully onto your back for 2-3 breaths, then roll back into freestyle. This teaches you to rotate your body as a unit rather than just turning your head, and helps remove the fear of not having your face in the water.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2485/","author":"Imported from swim plan","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:3f8e5871-4895-48c9-928d-dc1bc134f57b','wger-english-2026-09-08',1615,'2026-08-27T18:17:02.510360+02:00','dbe2e773e2404c351f007c82af0e1e62af1c60c44c80f7db11b1ea60c61e5f0a','{"name":"Treadmill Cardio","instructions":"It''s a cardiovascular workout performed on a treadmill to improve endurance, burn calories, and promote heart health. It offers multiple benefits, such as the ability to easily adjust speed and incline, allowing for a variety of workouts, from hill walking to high-intensity interval training (HIIT) and tempo runs. To optimize results, it''s important to vary your workouts. Benefits of Treadmill Cardio: Improved Cardiovascular Health: Regular aerobic exercise on a treadmill strengthens the heart and lungs, which can help prevent heart disease. Weight Loss: By burning calories, treadmill training can be an effective tool for weight loss and maintaining a healthy weight. Muscle Strengthening: It strengthens the muscles in the legs and glutes, helping to prevent muscle loss, which is especially important with age. Training Flexibility: Allows you to vary speed, incline, and intervals, making your workout more dynamic and adaptable to different fitness levels. Types of Treadmill Training: Hill Walking: Increasing the incline of the treadmill and walking at a brisk pace can improve endurance and work your leg muscles. Endurance Jog: A run at a comfortable, steady pace that keeps your heart rate in a target zone (such as Zone 2) to build endurance. Interval Training: Alternating periods of high intensity (fast running) with periods of low intensity (easy walking or jogging) to maximize calorie burn and cardiovascular improvement. Tempo Run: A run at a steady, sustained pace that is slightly faster than a normal jog, which challenges your ability to sustain a more intense effort for an extended period.","equipment":["none (bodyweight exercise)"],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1615/","author":"Tierrasverdes","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:9a5d36b8-7fa5-4705-8e9b-fafa211a13d6','wger-english-2026-09-08',2483,'2026-07-22T07:50:33.377710+02:00','fe81f44d580c7f216ab6e31063bce973015029363f7a535d793d584a7486d179','{"name":"Wall-Hold Rotation","instructions":"Hold the pool wall or edge with one hand, body horizontal at the surface, legs kicking gently behind you. Keep your face in the water, exhaling continuously, then rotate your head to the side — not lifting it up — so one goggle stays in the water while the other clears the surface. Take a quick breath, then rotate your face back down to neutral. This isolates the head-rotation motion without any arm strokes to think about.","equipment":[],"media":null,"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/2483/","author":"Imported from swim plan","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb),
  ('wger:65d12ecf-54b8-466d-a412-e55c396cad69','wger-1652-media-pilot-2026-09-08',1652,'2026-06-19T18:49:43.204115+02:00','dfc6d321ce4819b1678c25c63a5ae81220aa8c584e7c7b373285bfd574b5f86f','{"name":"Dumbbell Romanian Deadlift","instructions":"This exercise involves holding a dumbbell in each hand and bending forward at the hips while keeping the back straight, then returning to a standing position. It primarily targets the hamstrings and glutes.","equipment":["Dumbbell"],"media":{"kind":"image","posterUrl":"/training/reference/wger-1652-dumbbell-romanian-deadlift.webp","alt":"Two views of a person holding one dumbbell in each hand: standing upright and hinging forward at the hips.","width":1200,"height":630,"mimeType":"image/webp","sha256":"434e5dad93148deff622079705db41b250dae8908f844d92a01349d1cd4361ef","source":{"provider":"wger","exerciseRecordId":1652,"assetId":590,"assetUuid":"0306c8c0-70cc-45d4-92de-6fa72ceaa834","assetUrl":"https://wger.de/media/exercise-images/1652/0306c8c0-70cc-45d4-92de-6fa72ceaa834.webp","author":"AlucardEvil40","authorHistory":["AlucardEvil40"],"license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"isAiGenerated":false,"modifications":"none"}},"source":{"provider":"wger","recordUrl":"https://wger.de/api/v2/exerciseinfo/1652/","author":"AlucardEvil40","license":{"shortName":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}}'::jsonb);

CREATE TRIGGER training_reference_library_records_immutable
  BEFORE UPDATE OR DELETE ON public.training_reference_library_records
  FOR EACH ROW EXECUTE FUNCTION private.reject_training_evidence_mutation();

CREATE TABLE public.training_manual_reference_routines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  subject_id uuid NOT NULL REFERENCES public.training_subjects(id) ON DELETE RESTRICT,
  created_by_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  create_request_id uuid NOT NULL,
  create_request_hash text NOT NULL CHECK (create_request_hash ~ '^[a-f0-9]{64}$'),
  status text NOT NULL CHECK (status IN ('active','archived')),
  current_revision bigint NOT NULL CHECK (current_revision > 0),
  title text NOT NULL CHECK (
    pg_catalog.length(title) BETWEEN 1 AND 120
    AND title = pg_catalog.btrim(title)
    AND title !~ '[[:cntrl:]]'
  ),
  created_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),
  archived_at timestamptz,
  UNIQUE (created_by_user_id, create_request_id),
  UNIQUE (id, subject_id),
  CHECK (((status = 'archived') = (archived_at IS NOT NULL)) IS TRUE)
);

CREATE TABLE public.training_manual_reference_routine_revisions (
  routine_id uuid NOT NULL REFERENCES public.training_manual_reference_routines(id) ON DELETE RESTRICT,
  revision bigint NOT NULL CHECK (revision > 0),
  routine_json jsonb NOT NULL,
  routine_hash text GENERATED ALWAYS AS (
    private.training_evidence_sha256(routine_json)
  ) STORED,
  authored_by_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),
  PRIMARY KEY (routine_id, revision),
  CHECK ((routine_json->>'schemaVersion' = 'manual-reference-routine.v1') IS TRUE),
  CHECK ((routine_json->>'routineId' = routine_id::text) IS TRUE),
  CHECK (((routine_json->>'revision')::bigint = revision) IS TRUE),
  CHECK ((routine_json->>'status' IN ('active','archived')) IS TRUE),
  CHECK ((routine_json#>>'{source,kind}' = 'manual_reference') IS TRUE),
  CHECK ((routine_json#>>'{source,reviewStatus}' = 'reference_unreviewed') IS TRUE),
  CHECK ((routine_json#>>'{source,screeningInfluence}' = 'none') IS TRUE)
);

ALTER TABLE public.training_manual_reference_routines
  ADD CONSTRAINT training_manual_reference_routines_current_revision_fk
  FOREIGN KEY (id, current_revision)
  REFERENCES public.training_manual_reference_routine_revisions(routine_id, revision)
  DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE public.training_manual_reference_routine_create_receipts (
  actor_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  request_id uuid NOT NULL,
  subject_id uuid NOT NULL REFERENCES public.training_subjects(id) ON DELETE RESTRICT,
  request_hash text NOT NULL CHECK (request_hash ~ '^[a-f0-9]{64}$'),
  routine_id uuid NOT NULL REFERENCES public.training_manual_reference_routines(id) ON DELETE RESTRICT,
  result_json jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),
  PRIMARY KEY (actor_user_id, request_id),
  CHECK ((result_json->>'routineId' = routine_id::text) IS TRUE),
  CHECK ((result_json->>'subjectId' = subject_id::text) IS TRUE)
);

CREATE TRIGGER training_manual_routine_revisions_immutable
  BEFORE UPDATE OR DELETE ON public.training_manual_reference_routine_revisions
  FOR EACH ROW EXECUTE FUNCTION private.reject_training_evidence_mutation();
CREATE TRIGGER training_manual_routine_receipts_immutable
  BEFORE UPDATE OR DELETE ON public.training_manual_reference_routine_create_receipts
  FOR EACH ROW EXECUTE FUNCTION private.reject_training_evidence_mutation();

CREATE INDEX training_manual_routines_subject_updated
  ON public.training_manual_reference_routines(subject_id, updated_at DESC);

CREATE OR REPLACE FUNCTION private.can_write_training_manual_reference_routine(p_subject_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT private.is_training_subject_owner(p_subject_id)
    OR private.is_training_subject_coach(p_subject_id, 'program:coach_publish');
$$;

CREATE OR REPLACE FUNCTION private.is_valid_manual_reference_routine_items(p_items jsonb)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_item jsonb;
  v_load_kg text;
BEGIN
  IF pg_catalog.jsonb_typeof(p_items) IS DISTINCT FROM 'array'
    OR pg_catalog.jsonb_array_length(p_items) NOT BETWEEN 1 AND 280
  THEN RETURN false; END IF;

  IF (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_array_elements(p_items))
      <> (SELECT pg_catalog.count(DISTINCT item->>'itemId') FROM pg_catalog.jsonb_array_elements(p_items) item)
  THEN RETURN false; END IF;

  FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(p_items) LOOP
    IF pg_catalog.jsonb_typeof(v_item) IS DISTINCT FROM 'object'
      OR pg_catalog.jsonb_typeof(v_item->'itemId') IS DISTINCT FROM 'string'
      OR (v_item->>'itemId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      OR NOT EXISTS (
        SELECT 1 FROM public.training_reference_library_records reference
        WHERE reference.reference_id = v_item->>'referenceExerciseId'
      )
    THEN RETURN false; END IF;

    IF v_item ? 'restSeconds' AND (
      pg_catalog.jsonb_typeof(v_item->'restSeconds') IS DISTINCT FROM 'number'
      OR (v_item->>'restSeconds')::numeric <> pg_catalog.trunc((v_item->>'restSeconds')::numeric)
      OR (v_item->>'restSeconds')::numeric NOT BETWEEN 0 AND 3600
    ) THEN RETURN false; END IF;

    IF v_item->>'kind' = 'strength' THEN
      IF NOT (
        private.jsonb_has_exact_keys(v_item, ARRAY['itemId','referenceExerciseId','kind','sets','reps','load'])
        OR private.jsonb_has_exact_keys(v_item, ARRAY['itemId','referenceExerciseId','kind','sets','reps','load','restSeconds'])
      ) OR pg_catalog.jsonb_typeof(v_item->'sets') IS DISTINCT FROM 'number'
        OR (v_item->>'sets')::numeric <> pg_catalog.trunc((v_item->>'sets')::numeric)
        OR (v_item->>'sets')::numeric NOT BETWEEN 1 AND 20
        OR pg_catalog.jsonb_typeof(v_item->'reps') IS DISTINCT FROM 'number'
        OR (v_item->>'reps')::numeric <> pg_catalog.trunc((v_item->>'reps')::numeric)
        OR (v_item->>'reps')::numeric NOT BETWEEN 1 AND 100
        OR NOT private.jsonb_has_exact_keys(v_item->'load', ARRAY['value','unit'])
        OR pg_catalog.jsonb_typeof(v_item#>'{load,value}') IS DISTINCT FROM 'string'
        OR pg_catalog.jsonb_typeof(v_item#>'{load,unit}') IS DISTINCT FROM 'string'
      THEN RETURN false; END IF;
      v_load_kg := private.canonical_training_load_kg(
        v_item#>>'{load,value}', v_item#>>'{load,unit}'
      );
      IF v_load_kg IS NULL OR v_load_kg::numeric > 1000 THEN RETURN false; END IF;
    ELSIF v_item->>'kind' = 'conditioning' THEN
      IF NOT (
        private.jsonb_has_exact_keys(v_item, ARRAY['itemId','referenceExerciseId','kind','durationSeconds'])
        OR private.jsonb_has_exact_keys(v_item, ARRAY['itemId','referenceExerciseId','kind','durationSeconds','restSeconds'])
      ) OR pg_catalog.jsonb_typeof(v_item->'durationSeconds') IS DISTINCT FROM 'number'
        OR (v_item->>'durationSeconds')::numeric <> pg_catalog.trunc((v_item->>'durationSeconds')::numeric)
        OR (v_item->>'durationSeconds')::numeric NOT BETWEEN 1 AND 86400
      THEN RETURN false; END IF;
    ELSE
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RETURN false;
END;
$$;

CREATE OR REPLACE FUNCTION private.build_manual_reference_routine_items(p_items jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT pg_catalog.jsonb_agg(
    item.value
      || pg_catalog.jsonb_build_object(
        'provenance', pg_catalog.jsonb_build_object(
          'snapshotId', reference.snapshot_id,
          'sourceRecordId', reference.source_record_id,
          'sourceRecordUpdatedAt', reference.source_record_updated_at,
          'recordSha256', reference.record_sha256
        ),
        'exerciseDisplay', reference.display_json
      )
    ORDER BY item.ordinality
  )
  FROM pg_catalog.jsonb_array_elements(p_items) WITH ORDINALITY item(value, ordinality)
  JOIN public.training_reference_library_records reference
    ON reference.reference_id = item.value->>'referenceExerciseId';
$$;

CREATE OR REPLACE FUNCTION private.build_manual_reference_routine_document(
  p_routine_id uuid,
  p_subject_id uuid,
  p_revision bigint,
  p_status text,
  p_title text,
  p_items jsonb,
  p_created_by jsonb,
  p_created_at timestamptz,
  p_updated_at timestamptz,
  p_archived_at timestamptz
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_items jsonb;
BEGIN
  v_items := private.build_manual_reference_routine_items(p_items);
  RETURN pg_catalog.jsonb_build_object(
    'schemaVersion','manual-reference-routine.v1',
    'routineId',p_routine_id,
    'subjectId',p_subject_id,
    'revision',p_revision,
    'status',p_status,
    'title',p_title,
    'source',pg_catalog.jsonb_build_object(
      'kind','manual_reference',
      'snapshotIds',pg_catalog.jsonb_build_array(
        'wger-english-2026-09-08','wger-1652-media-pilot-2026-09-08'
      ),
      'reviewStatus','reference_unreviewed',
      'screeningInfluence','none'
    ),
    'items',v_items,
    'createdBy',p_created_by,
    'createdAt',p_created_at,
    'updatedAt',p_updated_at,
    'archivedAt',p_archived_at
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.create_training_manual_reference_routine(
  p_request_id uuid,
  p_subject_id uuid,
  p_title text,
  p_items jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_receipt public.training_manual_reference_routine_create_receipts%ROWTYPE;
  v_routine_id uuid := gen_random_uuid();
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_hash text;
  v_actor_kind text;
  v_document jsonb;
BEGIN
  IF p_request_id IS NULL OR p_subject_id IS NULL
    OR p_title IS NULL OR p_title <> pg_catalog.btrim(p_title)
    OR pg_catalog.length(p_title) NOT BETWEEN 1 AND 120
    OR p_title ~ '[[:cntrl:]]'
    OR private.is_valid_manual_reference_routine_items(p_items) IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'invalid manual reference routine' USING ERRCODE = '22023'; END IF;
  IF private.can_write_training_manual_reference_routine(p_subject_id) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'manual reference routine write is not authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(auth.uid()::text || ':' || p_request_id::text, 0)
  );
  v_hash := private.training_evidence_sha256(pg_catalog.jsonb_build_object(
    'operation','manual_routine_create','subjectId',p_subject_id,
    'title',p_title,'items',p_items
  ));
  SELECT * INTO v_receipt
  FROM public.training_manual_reference_routine_create_receipts receipt
  WHERE receipt.actor_user_id = auth.uid() AND receipt.request_id = p_request_id;
  IF FOUND THEN
    IF v_receipt.subject_id IS DISTINCT FROM p_subject_id
      OR v_receipt.request_hash IS DISTINCT FROM v_hash
    THEN RAISE EXCEPTION 'manual routine request ID reused with different content'
      USING ERRCODE = 'PT409'; END IF;
    RETURN v_receipt.result_json;
  END IF;

  v_actor_kind := CASE WHEN private.is_training_subject_owner(p_subject_id)
    THEN 'athlete' ELSE 'coach' END;
  v_document := private.build_manual_reference_routine_document(
    v_routine_id,p_subject_id,1,'active',p_title,p_items,
    pg_catalog.jsonb_build_object('kind',v_actor_kind,'userId',auth.uid()),
    v_now,v_now,NULL
  );
  INSERT INTO public.training_manual_reference_routines(
    id,subject_id,created_by_user_id,create_request_id,create_request_hash,
    status,current_revision,title,created_at,updated_at
  ) VALUES (
    v_routine_id,p_subject_id,auth.uid(),p_request_id,v_hash,
    'active',1,p_title,v_now,v_now
  );
  INSERT INTO public.training_manual_reference_routine_revisions(
    routine_id,revision,routine_json,authored_by_user_id,created_at
  ) VALUES (v_routine_id,1,v_document,auth.uid(),v_now);
  INSERT INTO public.training_manual_reference_routine_create_receipts(
    actor_user_id,request_id,subject_id,request_hash,routine_id,result_json,created_at
  ) VALUES (auth.uid(),p_request_id,p_subject_id,v_hash,v_routine_id,v_document,v_now);
  RETURN v_document;
END;
$$;

CREATE OR REPLACE FUNCTION public.read_training_manual_reference_routine(p_routine_id uuid)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT revision.routine_json
  FROM public.training_manual_reference_routines routine
  JOIN public.training_manual_reference_routine_revisions revision
    ON revision.routine_id = routine.id AND revision.revision = routine.current_revision
  WHERE routine.id = p_routine_id
    AND private.can_write_training_manual_reference_routine(routine.subject_id);
$$;

CREATE OR REPLACE FUNCTION public.list_training_manual_reference_routines(p_subject_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_routines jsonb;
BEGIN
  IF private.can_write_training_manual_reference_routine(p_subject_id) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'manual reference routine read is not authorized' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'routineId',routine.id,
    'subjectId',routine.subject_id,
    'revision',routine.current_revision,
    'status',routine.status,
    'title',routine.title,
    'itemCount',pg_catalog.jsonb_array_length(revision.routine_json->'items'),
    'updatedAt',routine.updated_at,
    'archivedAt',routine.archived_at
  ) ORDER BY routine.updated_at DESC, routine.id), '[]'::jsonb)
  INTO v_routines
  FROM (
    SELECT * FROM public.training_manual_reference_routines
    WHERE subject_id = p_subject_id
    ORDER BY updated_at DESC, id
    LIMIT 100
  ) routine
  JOIN public.training_manual_reference_routine_revisions revision
    ON revision.routine_id = routine.id AND revision.revision = routine.current_revision;
  RETURN pg_catalog.jsonb_build_object(
    'schemaVersion','manual-reference-routine-list.v1',
    'subjectId',p_subject_id,
    'routines',v_routines
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.update_training_manual_reference_routine(
  p_routine_id uuid,
  p_expected_revision bigint,
  p_title text,
  p_items jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_routine public.training_manual_reference_routines%ROWTYPE;
  v_current jsonb;
  v_document jsonb;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  IF p_routine_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision < 1
    OR p_title IS NULL OR p_title <> pg_catalog.btrim(p_title)
    OR pg_catalog.length(p_title) NOT BETWEEN 1 AND 120
    OR p_title ~ '[[:cntrl:]]'
    OR private.is_valid_manual_reference_routine_items(p_items) IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'invalid manual reference routine' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_routine FROM public.training_manual_reference_routines
    WHERE id = p_routine_id FOR UPDATE;
  IF NOT FOUND OR private.can_write_training_manual_reference_routine(v_routine.subject_id) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'manual reference routine write is not authorized' USING ERRCODE = '42501';
  END IF;
  IF v_routine.status <> 'active' OR v_routine.current_revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'manual reference routine changed concurrently' USING ERRCODE = 'PT409';
  END IF;
  SELECT routine_json INTO STRICT v_current
  FROM public.training_manual_reference_routine_revisions
  WHERE routine_id = p_routine_id AND revision = v_routine.current_revision;
  v_document := private.build_manual_reference_routine_document(
    p_routine_id,v_routine.subject_id,v_routine.current_revision+1,'active',p_title,p_items,
    v_current->'createdBy',v_routine.created_at,v_now,NULL
  );
  INSERT INTO public.training_manual_reference_routine_revisions(
    routine_id,revision,routine_json,authored_by_user_id,created_at
  ) VALUES (p_routine_id,v_routine.current_revision+1,v_document,auth.uid(),v_now);
  UPDATE public.training_manual_reference_routines
  SET current_revision=current_revision+1,title=p_title,updated_at=v_now
  WHERE id=p_routine_id;
  RETURN v_document;
END;
$$;

CREATE OR REPLACE FUNCTION public.archive_training_manual_reference_routine(
  p_routine_id uuid,
  p_expected_revision bigint
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_routine public.training_manual_reference_routines%ROWTYPE;
  v_current jsonb;
  v_document jsonb;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  IF p_routine_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision < 1 THEN
    RAISE EXCEPTION 'invalid manual reference routine archive' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_routine FROM public.training_manual_reference_routines
    WHERE id = p_routine_id FOR UPDATE;
  IF NOT FOUND OR private.can_write_training_manual_reference_routine(v_routine.subject_id) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'manual reference routine archive is not authorized' USING ERRCODE = '42501';
  END IF;
  IF v_routine.status = 'archived' AND v_routine.current_revision = p_expected_revision + 1 THEN
    RETURN pg_catalog.jsonb_build_object(
      'routineId',p_routine_id,'revision',v_routine.current_revision,'status','archived'
    );
  END IF;
  IF v_routine.status <> 'active' OR v_routine.current_revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'manual reference routine changed concurrently' USING ERRCODE = 'PT409';
  END IF;
  SELECT routine_json INTO STRICT v_current
  FROM public.training_manual_reference_routine_revisions
  WHERE routine_id = p_routine_id AND revision = v_routine.current_revision;
  v_document := v_current || pg_catalog.jsonb_build_object(
    'revision',v_routine.current_revision+1,
    'status','archived','updatedAt',v_now,'archivedAt',v_now
  );
  INSERT INTO public.training_manual_reference_routine_revisions(
    routine_id,revision,routine_json,authored_by_user_id,created_at
  ) VALUES (p_routine_id,v_routine.current_revision+1,v_document,auth.uid(),v_now);
  UPDATE public.training_manual_reference_routines
  SET status='archived',current_revision=current_revision+1,updated_at=v_now,archived_at=v_now
  WHERE id=p_routine_id;
  RETURN pg_catalog.jsonb_build_object(
    'routineId',p_routine_id,'revision',v_routine.current_revision+1,'status','archived'
  );
END;
$$;

ALTER TABLE public.training_reference_library_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.training_manual_reference_routines ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.training_manual_reference_routine_revisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.training_manual_reference_routine_create_receipts ENABLE ROW LEVEL SECURITY;

CREATE POLICY training_manual_routines_read ON public.training_manual_reference_routines
  FOR SELECT TO authenticated
  USING (private.can_write_training_manual_reference_routine(subject_id));
CREATE POLICY training_manual_routine_revisions_read ON public.training_manual_reference_routine_revisions
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.training_manual_reference_routines routine
    WHERE routine.id = routine_id
      AND private.can_write_training_manual_reference_routine(routine.subject_id)
  ));
CREATE POLICY training_manual_routine_receipts_read ON public.training_manual_reference_routine_create_receipts
  FOR SELECT TO authenticated
  USING (actor_user_id = auth.uid()
    AND private.can_write_training_manual_reference_routine(subject_id));

REVOKE ALL ON public.training_reference_library_records,
  public.training_manual_reference_routines,
  public.training_manual_reference_routine_revisions,
  public.training_manual_reference_routine_create_receipts
  FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.training_manual_reference_routines,
  public.training_manual_reference_routine_revisions,
  public.training_manual_reference_routine_create_receipts TO authenticated;
GRANT SELECT ON public.training_reference_library_records,
  public.training_manual_reference_routines,
  public.training_manual_reference_routine_revisions,
  public.training_manual_reference_routine_create_receipts TO service_role;

REVOKE ALL ON FUNCTION private.can_write_training_manual_reference_routine(uuid),
  private.is_valid_manual_reference_routine_items(jsonb),
  private.build_manual_reference_routine_items(jsonb),
  private.build_manual_reference_routine_document(uuid,uuid,bigint,text,text,jsonb,jsonb,timestamptz,timestamptz,timestamptz),
  public.create_training_manual_reference_routine(uuid,uuid,text,jsonb),
  public.read_training_manual_reference_routine(uuid),
  public.list_training_manual_reference_routines(uuid),
  public.update_training_manual_reference_routine(uuid,bigint,text,jsonb),
  public.archive_training_manual_reference_routine(uuid,bigint)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION private.can_write_training_manual_reference_routine(uuid)
  TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.create_training_manual_reference_routine(uuid,uuid,text,jsonb),
  public.read_training_manual_reference_routine(uuid),
  public.list_training_manual_reference_routines(uuid),
  public.update_training_manual_reference_routine(uuid,bigint,text,jsonb),
  public.archive_training_manual_reference_routine(uuid,bigint)
  TO authenticated;
